            });

            insertResourceAlertConfig(db, {
                contract_id: "CTEST1234",
                channel_type: "webhook",
                channel_target: "https://webhook2.example.com",
                cpu_limit: 100_000_000,
                mem_limit: 50_000_000,
            });

            const resourceData = {
                cpuInstructions: 85_000_000,
