const TIMEOUT_MS = 10_000;

function severityEmoji(event: AlertEvent): string {
    if (event.type === "alert_resolved") return "✅";
    if (event.type === "state_changed") return "🔄";
    if (event.severity === "critical") return "🔴";
    return "⚠️";
}

function buildBlocks(event: AlertEvent): any[] {
    const icon = severityEmoji(event);
    const contractDisplay = event.contractName ?? event.contractId;

    let status: string;
    if (event.type === "resource_alert") {
        const resourceType = event.resource.type === "cpu" ? "CPU" : "Memory";
        status = `Resource ${resourceType} ${event.severity === "critical" ? "CRITICAL" : "Warning"}`;
    } else if (event.type === "threshold_crossed") {
        status = `TTL ${event.severity === "critical" ? "CRITICAL" : "Warning"}`;
    } else if (event.type === "state_changed") {
        const diffLabel = event.diff.diffType.charAt(0).toUpperCase() + event.diff.diffType.slice(1);
        status = `State ${diffLabel}`;
    } else {
        status = "Alert Resolved";
    }

    const header = {
        type: "header",
        text: {
            type: "plain_text",
            text: `${icon} ${status} — ${contractDisplay}`,
            emoji: true,
        },
    };

    let details: any;
    if (event.type === "resource_alert") {
        const usageStr = event.resource.currentUsage.toLocaleString();
        const limitStr = event.resource.limit.toLocaleString();
        details = {
            type: "section",
            fields: [
                { type: "mrkdwn", text: `*Resource:*\n${event.resource.type.toUpperCase()}` },
                { type: "mrkdwn", text: `*Network:*\n${event.network}` },
                { type: "mrkdwn", text: `*Usage:*\n${usageStr} / ${limitStr} (${event.resource.usagePercent}%)` },
                { type: "mrkdwn", text: `*Severity:*\n${event.severity}` },
            ],
        };
    } else if (event.type === "state_changed") {
        const entryLabel = event.entry.label ?? event.entry.type;
        const oldVal = event.diff.oldValueXdr ?? "(none)";
        const newVal = event.diff.newValueXdr ?? "(none)";
        details = {
            type: "section",
            fields: [
                { type: "mrkdwn", text: `*Entry:*\n${entryLabel}` },
                { type: "mrkdwn", text: `*Network:*\n${event.network}` },
                { type: "mrkdwn", text: `*Change Type:*\n${event.diff.diffType}` },
                { type: "mrkdwn", text: `*Old Value:*\n\`${oldVal}\`` },
                { type: "mrkdwn", text: `*New Value:*\n\`${newVal}\`` },
            ],
        };
    } else {
        details = {
            type: "section",
            fields: [
                { type: "mrkdwn", text: `*Entry:*\n${event.entry.label ?? event.entry.type}` },
                { type: "mrkdwn", text: `*Network:*\n${event.network}` },
                { type: "mrkdwn", text: `*Remaining TTL:*\n${event.threshold.currentRemainingLedgers.toLocaleString()} ledgers (${event.threshold.approximateTimeRemaining})` },
                { type: "mrkdwn", text: `*Threshold:*\n${event.threshold.configuredLedgers.toLocaleString()} ledgers` },
            ],
        };
    }

    const footer = {
        type: "context",
        elements: [
            { type: "mrkdwn", text: `Severity: *${event.severity}* | Run \`sorokeep status ${event.contractId}\` for details.` },
        ],
    };

    return [header, details, footer];
}

function buildFallbackText(event: AlertEvent): string {
    const icon = severityEmoji(event);
    const contractDisplay = event.contractName ?? event.contractId;

    if (event.type === "resource_alert") {
        const resourceType = event.resource.type === "cpu" ? "CPU" : "Memory";
        const status = `Resource ${resourceType} ${event.severity === "critical" ? "CRITICAL" : "Warning"}`;
        return (
            `${icon} ${status} — ${contractDisplay} (${event.network}) | ` +
            `Usage: ${event.resource.currentUsage.toLocaleString()} / ${event.resource.limit.toLocaleString()} ` +
            `(${event.resource.usagePercent}%)`
        );
    } else if (event.type === "state_changed") {
        const diffLabel = event.diff.diffType.charAt(0).toUpperCase() + event.diff.diffType.slice(1);
        return (
            `${icon} State ${diffLabel} — ${contractDisplay} (${event.network}) | ` +
            `Entry: ${event.entry.label ?? event.entry.type} | ` +
            `Old: ${event.diff.oldValueXdr ?? "(none)"} → New: ${event.diff.newValueXdr ?? "(none)"}`
        );
    } else if (event.type === "threshold_crossed") {
        const status = `TTL ${event.severity === "critical" ? "CRITICAL" : "Warning"}`;
        return (
            `${icon} ${status} — ${contractDisplay} (${event.network}) | ` +
            `Remaining: ${event.threshold.currentRemainingLedgers.toLocaleString()} ledgers ` +
            `(${event.threshold.approximateTimeRemaining}) | ` +
            `Threshold: ${event.threshold.configuredLedgers.toLocaleString()} ledgers`
        );
    } else {
        return `${icon} Alert Resolved — ${contractDisplay} (${event.network})`;
    }
}

function resolveSlackToken(): string {
    const token = process.env.SOROKEEP_SLACK_TOKEN || loadConfig().slackToken;
    if (!token) {
        throw new Error("Slack token not configured. Set SOROKEEP_SLACK_TOKEN or slackToken in config.");
    }
    return token;
}

export async function sendSlackAlert(channel: string, event: AlertEvent): Promise<void> {
    const token = resolveSlackToken();
    const payload = {
        channel,
        text: buildFallbackText(event),
        blocks: buildBlocks(event),
    };

    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), TIMEOUT_MS);

    let response: Response;
    try {
        response = await fetch("https://slack.com/api/chat.postMessage", {
            method: "POST",
            headers: {
                Authorization: `Bearer ${token}`,
                "Content-Type": "application/json",
            },
            body: JSON.stringify(payload),
            signal: controller.signal,
        });
    } finally {
        clearTimeout(timeout);
    }

    if (!response.ok) {
        throw new Error(`Slack API request failed: HTTP ${response.status}`);
    }

    const data = await response.json() as { ok?: boolean; error?: string };
    if (!data.ok) {
        throw new Error(`Slack API error: ${data.error ?? "unknown_error"}`);
    }
}

export class SlackChannel {
    constructor(private readonly webhookUrl: string) {
        if (!webhookUrl || !webhookUrl.startsWith("http")) {
            throw new Error("Invalid Slack webhook URL");
        }
    }

    async send(event: AlertEvent): Promise<void> {
        logger.debug(`Sending Slack alert to webhook`, { type: event.type, contractId: event.contractId });

        const customMessage = renderAlertTemplate("slack", event);
        let payload: { text?: string; blocks?: any[] };

        if (customMessage !== null) {
            try {
                const parsed = JSON.parse(customMessage);
                if (parsed && typeof parsed === "object") {
                    if (Array.isArray(parsed)) {
                        payload = { text: buildFallbackText(event), blocks: parsed };
                    } else {
                        payload = {
                            text: parsed.text ?? buildFallbackText(event),
                            blocks: parsed.blocks,
                        };
                    }
                } else {
                    payload = { text: customMessage };
                }
            } catch {
                payload = { text: customMessage };
            }
        } else {
            payload = {
                text: buildFallbackText(event),
                blocks: buildBlocks(event),
            };
        }

        const controller = new AbortController();
        const timeout = setTimeout(() => controller.abort(), TIMEOUT_MS);

        let response: Response;
        try {
            response = await fetch(this.webhookUrl, {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify(payload),
                signal: controller.signal,
            });
        } finally {
            clearTimeout(timeout);
        }

        if (!response.ok) {
            let errorMsg = `HTTP ${response.status}`;
            try {
                const text = await response.text();
                if (text) errorMsg += `: ${text}`;
            } catch {
                // ignore
            }
            throw new Error(errorMsg);
        }

        logger.debug(`Slack alert delivered successfully`);
    }
}

import fs from "node:fs";

export type SchemaDictionary = Record<string, string>;

function normalizeSchemaCandidate(input: unknown): SchemaDictionary {
  if (typeof input !== "object" || input === null || Array.isArray(input)) {
    throw new Error(
      "Schema configuration error: schema JSON must be a top-level object mapping raw keys to labels",
    );
  }

  const candidate = input as Record<string, unknown>;
  const out: SchemaDictionary = {};

  for (const [k, v] of Object.entries(candidate)) {
    if (typeof v !== "string") {
      throw new Error(
        `Schema configuration error: schema value for key '${k}' must be a string label`,
      );
    }
    out[k] = v;
  }

  return out;
}

export function loadSchema(schemaPath: string): SchemaDictionary {
    try {
        const raw = fs.readFileSync(schemaPath, "utf8");
        let parsed: unknown;
        try {
            parsed = JSON.parse(raw);
        } catch (err) {
            const msg = err instanceof Error ? err.message : String(err);
            throw new Error(`Schema configuration error: malformed JSON in schema file: ${msg}`, { cause: err });
        }

        return normalizeSchemaCandidate(parsed);
    } catch (err) {
        const nodeErr = err as NodeJS.ErrnoException;
        if (nodeErr?.code === "ENOENT") {
            throw new Error(
                `Schema configuration error: schema file not found at '${schemaPath}'`,
                { cause: err } // Pass the original caught variable directly
            );
        }

        const msg = nodeErr?.message ?? String(err);
        throw new Error(`Schema configuration error: failed to load schema file: ${msg}`, { cause: err }); // Pass the original caught variable directly
    }
}
function applySchemaToValue(value: unknown, schema: SchemaDictionary): unknown {
  if (typeof value === "string") {
    return schema[value] ?? value;
  }

  if (Array.isArray(value)) {
    return value.map((v) => applySchemaToValue(v, schema));
  }

  if (typeof value === "object" && value !== null) {
    const obj = value as Record<string, unknown>;
    const out: Record<string, unknown> = {};
    for (const [key, v] of Object.entries(obj)) {
      const nextKey = schema[key] ?? key;
      out[nextKey] = applySchemaToValue(v, schema);
    }
    return out;
  }

  return value;
}

export function applySchema(data: any, schema: SchemaDictionary): any {
  if (!schema || Object.keys(schema).length === 0) return data;
  return applySchemaToValue(data, schema);
}

/**
 * Wrapper used by CLI inspect formatting: loads schema when schemaPath is provided.
 *
 * - If schemaPath is undefined, returns schema map as undefined (caller should skip transformation)
 * - If schemaPath is provided, loads+validates schema and applies translation to `data`.
 */
export function loadAndApplySchema(data: any, schemaPath?: string): any {
  if (!schemaPath) return data;
  const schema = loadSchema(schemaPath);
  return applySchema(data, schema);
}

import { Command } from "commander";
import chalk from "chalk";
import ora from "ora";
import { getDatabase } from "../db/database.js";
import { inspectContract } from "../core/inspect.js";
import { statusIndicator, formatContractID } from "../utils/formatting.js";
import { getLogger } from "../logging/index.js";

const logger = getLogger().child({ component: "InspectCommand" });

export function registerInspectCommand(program: Command): void {
    program
        .command("inspect <contractId>")
        .description("Inspect contract storage and token balances")
        .option("--entry <keyOrShortcut>", "Specific entry key XDR or shortcut (e.g. balance:<address>)", collect, [])
        .option("--network <network>", "The stellar network to use (testnet, mainnet)")
        .option("-r, --rpc-url <url>", "Custom RPC URL")
        .action(async (contractId: string, options: { entry: string[]; network?: string; rpcUrl?: string }) => {
            const spinner = ora(`Inspecting contract ${formatContractID(contractId)}...`).start();
            try {
                const db = getDatabase();
                const result = await inspectContract(db, contractId, {
                    entries: options.entry,
                    network: options.network,
                    rpcUrl: options.rpcUrl,
                });

                if (!result.success) {
                    spinner.fail(chalk.red("Inspection failed"));
                    console.error(chalk.red(result.error));
                    process.exit(1);
                    return;
                }

                const displayName = result.contractName ?? formatContractID(contractId);
                spinner.succeed(chalk.green(`Inspected ${displayName}`));

                console.log();
                console.log(`  Contract: ${chalk.bold.cyan(displayName)} (${chalk.dim(formatContractID(contractId))})`);
                console.log(`  Network:  ${chalk.cyan(result.network)}`);
                if (result.isSac) {
                    console.log(`  Type:     ${chalk.cyan("Stellar Asset Contract (SAC)")}`);
                    console.log(`  Decimals: ${chalk.cyan(result.decimals)}`);
                }
                console.log();

                if (!result.results || result.results.length === 0) {
                    console.log(chalk.yellow("  No entries specified to inspect. Use --entry <keyXdr> or --entry balance:<address>"));
                    console.log();
                    return;
                }

                for (const item of result.results) {
                    console.log(chalk.bold(`  Entry: ${item.inputEntry}`));
                    if (item.type === "balance" && item.balance) {
                        console.log(`    Balance:    ${chalk.bold.green(item.formattedBalance)}`);
                        console.log(`    Raw Amount: ${item.balance.amount.toString()}`);
                        console.log(`    Authorized: ${item.balance.authorized}`);
                        console.log(`    Clawback:   ${item.balance.clawback}`);
                    }

                    if (!item.found || item.status === "unknown" || item.remainingTTL == null) {
                        console.log(chalk.red(`    Error: Target key is not active on-chain`));
                    } else {
                        if (item.type === "raw" && item.decodedValue) {
                            console.log(chalk.cyan(`    Decoded Value:`));
                            const formattedJson = JSON.stringify(item.decodedValue, null, 2)
                                .split('\n')
                                .map(line => `      ${line}`)
                                .join('\n');
                            console.log(formattedJson);
                        }
                        console.log(
                            `    TTL:        ${item.remainingTTL.toLocaleString()} ledgers (${item.approximateTimeRemaining})  ${statusIndicator(item.status as any)}`,
                        );
                    }
                    console.log();
                }
            } catch (error: any) {
                const msg = error instanceof Error ? error.message : String(error);
                spinner.fail(chalk.red("Error"));
                console.error(chalk.red(`Error: ${msg}`));
                logger.error("Inspect command failed", { error: msg });
                process.exit(1);
            }
        });
}

function collect(value: string, previous: string[]): string[] {
    return previous.concat([value]);
}

import { Command } from "commander";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import { getDatabase } from "../db/database.js";
import { createMcpServer } from "../mcp/server.js";

export function registerMcpCommand(program: Command): void {
  program
    .command("mcp")
    .description("Start the Model Context Protocol (MCP) server on stdio transport")
    .action(async () => {
      try {
        const server = createMcpServer(() => getDatabase());
        const transport = new StdioServerTransport();
        await server.connect(transport);
      } catch (error: any) {
        console.error("MCP server error:", error);
        process.exit(1);
      }
    });
}

import { Command } from "commander";
import chalk from "chalk";
import { getDatabase } from "../db/database.js";
import { getContract, setContractActiveStatus } from "../db/repositories.js";
import { formatContractID } from "../utils/formatting.js";
import { getLogger } from "../logging/index.js";

const logger = getLogger().child({ component: "PauseCommand" });

export const registerPauseCommand = (program: Command): void => {
    program
        .command("pause <contract-id>")
        .description("Temporarily pause daemon polling and alerting for a contract")
        .action(async (contractId: string) => {
            try {
                const db = getDatabase();
                const contract = getContract(db, contractId);

                if (!contract) {
                    console.log(chalk.red(`Contract ${formatContractID(contractId)} is not being watched.`));
                    process.exit(1);
                    return;
                }

                setContractActiveStatus(db, contractId, false);
                console.log(chalk.green(`Successfully paused monitoring for ${formatContractID(contractId)}.`));
                console.log(chalk.dim(`Run 'sorokeep resume ${formatContractID(contractId)}' to re-enable.`));
            } catch (error: any) {
                const errorMessage = error instanceof Error ? error.message : String(error);
                logger.error("Pause command failed", { error: errorMessage });
                console.log(chalk.red(`Failed to pause contract: ${errorMessage}`));
                process.exit(1);
            }
        });
};

