import { Command } from "commander";
import chalk from "chalk";
import readline from "node:readline";
import ora from "ora";
import { getDatabase } from "../db/database.js";
import { deleteContract, getContract } from "../db/repositories.js";
import { getLogger } from "../logging/index.js";
import {
  classifyTTL,
  formatContractID,
  formatTimeToCloseLedger,
  statusIndicator,
} from "../utils/formatting.js";
import { watchContract } from "../core/watch.js";
import { loadWatchContractsFile } from "../utils/watch-config.js";

const logger = getLogger().child({ component: "WatchCommand" });

export const registerWatchCommand = (program: Command): void => {
  program
    .command("watch [contract-id]")
    .description("Register and start watching a contract")
    .option("-n, --name <name>", "A human-readable name for the contract")
    .option(
      "--network <network>",
      "The stellar network to use (testnet, mainnet)",
      "testnet",
    )
    .option("-r, --rpc-url <url>", "Custom RPC URL")
    .option(
      "--storage-keys <keys>",
      "Comma-separated base64 XDR storage keys to watch",
    )
    .option(
      "--no-introspection",
      "Skip automatic contract introspection (WASM code fetching)",
    )
    .option(
      "--from-file <path>",
      "Load multiple contract registrations from a YAML or JSON file",
    )
    .action(async (contractId, options) => {
      try {
        const db = getDatabase();

        if (options.fromFile) {
          const configs = loadWatchContractsFile(options.fromFile);
          const results = [] as Array<{
            contractId: string;
            name?: string;
            network: string;
            status: "SUCCESS" | "FAILED";
            message: string;
          }>;

          for (const config of configs) {
            const watchResult = await watchContract(db, {
              contractId: config.contractId,
              network: config.network,
              name: config.name,
              rpcUrl: config.rpcUrl,
              storageKeys: config.storageKeys,
              noIntrospection: config.noIntrospection,
            });

            results.push({
              contractId: config.contractId,
              name: config.name,
              network: config.network,
              status: watchResult.success ? "SUCCESS" : "FAILED",
              message: watchResult.success
                ? `Registered ${config.name ?? formatContractID(config.contractId)}`
                : watchResult.error,
            });
          }

          printBatchSummary(results);

          if (results.some((result) => result.status === "FAILED")) {
            process.exit(1);
          }
          return;
        }

        if (!contractId) {
          console.log(
            chalk.red(
              "A contract ID is required unless --from-file is provided.",
            ),
          );
          process.exit(1);
          return;
        }

        const displayId = formatContractID(contractId);
        const spinner = ora(
          `Registering contract ${formatContractID(contractId)} and discovering entries...`,
        ).start();
        const watchResult = await watchContract(db, {
          contractId,
          network: options.network,
          name: options.name,
          rpcUrl: options.rpcUrl,
          storageKeys: options.storageKeys,
          noIntrospection: options.noIntrospection,
        });
        if (!watchResult.success) {
          spinner.fail(chalk.red(watchResult.error));
          process.exit(1);
          return;
        }
        spinner.succeed(
          chalk.green(
            `Contract ${options.name || displayId} registered successfully.`,
          ),
        );
        const entryCount =
          1 +
          (watchResult.wasm ? 1 : 0) +
          (options.storageKeys ? options.storageKeys.split(",").length : 0);

        console.log(
          `\n  Contract: ${chalk.cyan(options.name ?? displayId)} (${chalk.dim(displayId)})`,
        );
        console.log(`  Network:  ${chalk.cyan(options.network)}`);
        console.log(`  Entries:  ${chalk.cyan(entryCount)} discovered`);

        const instanceTTL = watchResult.instance.remainingTTL;
        const instanceStatus = classifyTTL(instanceTTL);
        console.log(
          `  Instance TTL: ${instanceTTL.toLocaleString()} ledgers (${formatTimeToCloseLedger(instanceTTL)})  ${statusIndicator(instanceStatus)}`,
        );

        if (watchResult.wasm) {
          const wasmTTL = watchResult.wasm.remainingTTL;
          const wasmStatus = classifyTTL(wasmTTL);
          console.log(
            `  WASM Code TTL: ${wasmTTL.toLocaleString()} ledgers (${formatTimeToCloseLedger(wasmTTL)})  ${statusIndicator(wasmStatus)}`,
          );
        }

        if (watchResult.wasmWarning) {
          console.warn(chalk.yellow(`\n  ⚠ ${watchResult.wasmWarning}`));
        }

        console.log(
          chalk.dim(
            "\n  Run 'sorokeep status " +
              formatContractID(contractId) +
              "' to check TTLs anytime.",
          ),
        );
        console.log(
          chalk.dim(
            "  Run 'sorokeep guard " +
              formatContractID(contractId) +
              "' to enable auto-extension.",
          ),
        );
      } catch (error: any) {
        const errorMessage =
          error instanceof Error ? error.message : String(error);
        logger.error("Watch command failed", { error: errorMessage });
        console.log(chalk.red(`Failed to watch contract: ${errorMessage}`));
        process.exit(1);
      }
    });

  program
    .command("unwatch <contract-id>")
    .description("Remove a registered contract and clean up associated logs")
    .option("-y, --yes", "Skip confirmation prompt")
    .action(async (contractId: string, options: { yes?: boolean }) => {
      try {
        const db = getDatabase();
        const contract = getContract(db, contractId);

        if (!contract) {
          console.log(chalk.red(`Contract ${formatContractID(contractId)} is not being watched.`));
          process.exit(1);
          return;
        }

        const proceedWithDeletion = async (): Promise<void> => {
          deleteContract(db, contractId);
          console.log(chalk.green(`Successfully unwatched contract ${formatContractID(contractId)}.`));
        };

        if (options.yes) {
          await proceedWithDeletion();
        } else {
          const rl = readline.createInterface({
            input: process.stdin,
            output: process.stdout,
          });

          rl.question(
            chalk.yellow(`Are you sure you want to unwatch ${formatContractID(contractId)}? All associated logs, alerts, and policies will be permanently deleted. (y/N): `),
            async (answer) => {
              rl.close();
              if (answer.toLowerCase() === "y" || answer.toLowerCase() === "yes") {
                await proceedWithDeletion();
              } else {
                console.log("Unwatch cancelled.");
              }
            }
          );
        }
      } catch (error: any) {
        const errorMessage = error instanceof Error ? error.message : String(error);
        logger.error("Unwatch command failed", { error: errorMessage });
        console.log(chalk.red(`Failed to unwatch contract: ${errorMessage}`));
        process.exit(1);
      }
    });
};

function printBatchSummary(
  results: Array<{
    contractId: string;
    name?: string;
    network: string;
    status: "SUCCESS" | "FAILED";
    message: string;
  }>,
): void {
  const rows = results.map((result) => {
    const label = result.name ?? formatContractID(result.contractId);
    return `${result.status.padEnd(7)} | ${label.padEnd(18)} | ${result.network.padEnd(8)} | ${result.message}`;
  });

  const successCount = results.filter(
    (result) => result.status === "SUCCESS",
  ).length;
  const failureCount = results.length - successCount;

  console.log("\nBatch registration summary");
  console.log("STATUS  | CONTRACT           | NETWORK  | MESSAGE");
  console.log("--------|--------------------|----------|--------");
  for (const row of rows) {
    console.log(row);
  }
  console.log(`\n${successCount} succeeded, ${failureCount} failed`);
}

export interface AWSSecretsResolverConfig {
    region?: string;
    profile?: string;
}

export class AWSSecretsResolver {
    private region: string;
    private profile?: string;
    private clientPromise?: Promise<any>;

    constructor(config: AWSSecretsResolverConfig = {}) {
        this.region = config.region || "us-east-1";
        this.profile = config.profile;
    }

    private async getClient() {
        if (!this.clientPromise) {
            this.clientPromise = (async () => {
                const { SecretsManagerClient } = await import("@aws-sdk/client-secrets-manager");
                
                const clientConfig: any = { region: this.region };
                if (this.profile) {
                    const { fromIni } = await import("@aws-sdk/credential-providers");
                    clientConfig.credentials = fromIni({ profile: this.profile });
                }

                return new SecretsManagerClient(clientConfig);
            })();
        }
        return this.clientPromise;
    }

    public async resolveKey(secretId: string): Promise<string> {
        const client = await this.getClient();
        const { GetSecretValueCommand } = await import("@aws-sdk/client-secrets-manager");

        const command = new GetSecretValueCommand({ SecretId: secretId });
        const response = await client.send(command);

        if (!response.SecretString) {
            throw new Error(`SecretString is empty for secret: ${secretId}`);
        }

        return response.SecretString;
    }
}

import type Database from "better-sqlite3";
import { StellarRpcClient } from "../rpc/client.js";
import {
    getChannelAccounts,
    updateChannelBalance,
    insertChannelAccount,
    markChannelFunded,
    type ChannelAccount,
} from "../db/repositories.js";
import { getLogger } from "../logging/index.js";

const logger = getLogger().child({ component: "ChannelAccountPool" });

export interface ChannelSlot {
    publicKey: string;
    keypairSource: string | null;
}

export interface ChannelBalance {
    publicKey: string;
    balanceXlm: number | null;
    balanceCheckedAt: string | null;
}

/**
 * Pool of channel accounts for concurrent TTL extensions.
 *
 * Each account tracks its own sequence number on Stellar, so concurrent
 * transactions submitted through different accounts avoid sequence conflicts.
 * acquire() hands out a slot in round-robin order, blocking callers until
 * a slot is free. release() returns the slot and unblocks the next waiter.
 */
export class ChannelAccountPool {
    private readonly db: Database.Database;
    private readonly network: string;
    private readonly accounts: ChannelAccount[];
    /** Tracks which publicKeys are currently in use. */
    private readonly inUse = new Set<string>();
    /** Queue of resolve callbacks waiting for the next free slot. */
    private readonly waiters: Array<(slot: ChannelSlot) => void> = [];
    /** Round-robin cursor. */
    private cursor = 0;

    constructor(db: Database.Database, network: string) {
        this.db = db;
        this.network = network;
        this.accounts = getChannelAccounts(db, network);
    }

    /** Number of registered channel accounts. */
    size(): number {
        return this.accounts.length;
    }

    /**
     * Acquire an available channel account slot.
     * If all slots are in use, waits until one is released.
     */
    acquire(): Promise<ChannelSlot> {
        const slot = this.nextFreeSlot();
        if (slot) {
            this.inUse.add(slot.publicKey);
            return Promise.resolve(slot);
        }

        // All slots busy — queue the caller
        return new Promise<ChannelSlot>(resolve => {
            this.waiters.push(resolve);
        });
    }

    /**
     * Release a slot back to the pool.
     * Unblocks the oldest waiting acquire() call if any.
     */
    release(publicKey: string): void {
        this.inUse.delete(publicKey);

        if (this.waiters.length > 0) {
            const slot = this.nextFreeSlot();
            if (slot) {
                this.inUse.add(slot.publicKey);
                this.waiters.shift()!(slot);
            }
        }
    }

    /**
     * Returns current balance information for all accounts in the pool.
     * Reads from the DB — does not call the RPC.
     */
    getBalances(): ChannelBalance[] {
        return getChannelAccounts(this.db, this.network).map(a => ({
            publicKey: a.public_key,
            balanceXlm: a.balance_xlm,
            balanceCheckedAt: a.balance_checked_at,
        }));
    }

    /**
     * Fetch native XLM balances for all accounts from the RPC and persist them.
     * Errors per-account are logged and swallowed — does not throw.
     */
    async refreshBalances(rpcUrl?: string): Promise<void> {
        if (this.accounts.length === 0) return;

        const client = new StellarRpcClient(this.network, rpcUrl);

        await Promise.all(
            this.accounts.map(async account => {
                try {
                    const response = await (client as any).getAccount(account.public_key);
                    const nativeBalance = response.balances?.find(
                        (b: any) => b.asset_type === "native",
                    );
                    const xlm = nativeBalance ? parseFloat(nativeBalance.balance) : 0;
                    updateChannelBalance(this.db, account.public_key, xlm);
                } catch (err: unknown) {
                    const msg = err instanceof Error ? err.message : String(err);
                    logger.warn(`Failed to refresh balance for ${account.public_key}: ${msg}`);
                }
            }),
        );
    }

    // ─── Private ─────────────────────────────────────────────────────────────

    /**
     * Find the next free account in round-robin order.
     * Returns undefined if all accounts are in use.
     */
    private nextFreeSlot(): ChannelSlot | undefined {
        const n = this.accounts.length;
        for (let i = 0; i < n; i++) {
            const idx = (this.cursor + i) % n;
            const account = this.accounts[idx]!;
            if (!this.inUse.has(account.public_key)) {
                this.cursor = (idx + 1) % n;
                return { publicKey: account.public_key, keypairSource: account.keypair_source };
            }
        }
        return undefined;
    }
}

export interface FundChannelsResult {
    funded: number;
    txHash: string;
    errors: string[];
}

export function addChannel(
    db: Database.Database,
    publicKey: string,
    network: string,
    label?: string,
): void {
    insertChannelAccount(db, { public_key: publicKey, network, label });
}

export function listChannels(db: Database.Database, network: string): ChannelAccount[] {
    return getChannelAccounts(db, network);
}

export async function fundChannels(
    db: Database.Database,
    masterSecretKey: string,
    amountXlm: string,
    network: string,
    rpcUrl?: string,
): Promise<FundChannelsResult> {
    const accounts = getChannelAccounts(db, network);
    if (accounts.length === 0) {
        return { funded: 0, txHash: "", errors: [] };
    }

    const client = new StellarRpcClient(network, rpcUrl);
    const destinations = accounts.map((a) => ({
        publicKey: a.public_key,
        amountXlm,
    }));

    const result = await client.sendPayments(destinations, masterSecretKey);

    if (!result.success) {
        return { funded: 0, txHash: result.txHash, errors: [result.error ?? "Transaction failed"] };
    }

    for (const account of accounts) {
        markChannelFunded(db, account.public_key);
    }

    return { funded: accounts.length, txHash: result.txHash, errors: [] };
}

import { xdr, Address, scValToNative } from '@stellar/stellar-sdk';

export interface DecodedLedgerKey {
  contractId: string;
  symbol: any;
  durability: string;
}

export function decodeLedgerKey(base64Key: string): DecodedLedgerKey {
  const buf = Buffer.from(base64Key, 'base64');
  const key = xdr.LedgerKey.fromXDR(buf);
  
  if (key.switch() !== xdr.LedgerEntryType.contractData()) {
    throw new Error('Unsupported ledger entry type');
  }

  const contractData = key.contractData();
  const contractAddress = Address.fromScAddress(contractData.contract());
  const contractId = contractAddress.toString();

  const scValKey = contractData.key();
  let symbol: any;
  if (scValKey.switch() === xdr.ScValType.scvLedgerKeyContractInstance()) {
    symbol = 'ContractInstance';
  } else {
    try {
      symbol = scValToNative(scValKey);
    } catch {
      symbol = 'Unknown';
    }
  }

  const durabilityType = contractData.durability();
  let durability = 'Unknown';
  if (durabilityType.value === xdr.ContractDataDurability.persistent().value) {
    durability = 'Persistent';
  } else if (durabilityType.value === xdr.ContractDataDurability.temporary().value) {
    durability = 'Temporary';
  }

  return {
    contractId,
    symbol,
    durability
  };
}

import type Database from "better-sqlite3";
import { rpc, xdr, StrKey } from "@stellar/stellar-sdk";
import { getEntriesForContract, upsertEntry, getAllContracts } from "../db/repositories.js";
import { getLogger } from "../logging/index.js";

const logger = getLogger().child({ component: "Discovery" });

// ─── Public contract ──────────────────────────────────────────────────────────

export interface DiscoveryResult {
    /** Contract ID that was scanned. */
    contractId: string;
    /** Number of new storage keys discovered. */
    newKeysDiscovered: number;
    /** Total transactions scanned. */
    transactionsScanned: number;
    /** Error message if discovery failed. */
    error?: string;
}

export interface BatchDiscoveryResult {
    /** Total contracts scanned. */
    contractsScanned: number;
    /** Total new keys discovered across all contracts. */
    totalNewKeys: number;
    /** Per-contract results. */
    results: DiscoveryResult[];
    /** Errors that occurred during discovery. */
    errors: string[];
}

// ─── RPC URLs ──────────────────────────────────────────────────────────────────

const RPC_URLS: Record<string, string> = {
    testnet: "https://soroban-testnet.stellar.org",
    mainnet: "https://mainnet.sorobanrpc.com",
};

// ─── Core implementation ──────────────────────────────────────────────────────

/**
 * Discover new storage keys for a contract by scanning recent transactions.
 *
 * Uses the Stellar RPC `getEvents` endpoint to find contract invocation events,
 * then extracts ledger keys from the event data to discover persistent and
 * temporary storage entries that the contract has touched.
 *
 * This is Layer 2 of the discovery architecture — it learns keys over time
 * from observed contract activity.
 */
export async function discoverStorageKeys(
    db: Database.Database,
    contractId: string,
    network: string,
    rpcUrl?: string,
): Promise<DiscoveryResult> {
    const result: DiscoveryResult = {
        contractId,
        newKeysDiscovered: 0,
        transactionsScanned: 0,
    };

        const url = rpcUrl ?? RPC_URLS[network];
        if (!url) {
            result.error = `Unknown network "${network}"`;
            return result;
        }

    try {
        const server = new rpc.Server(url);

        // Get the latest ledger to set up the event window
        const health = await server.getHealth();
        const latestLedger = (health as any).latestLedger ?? 0;
        if (latestLedger === 0) {
            result.error = "Could not determine latest ledger";
            return result;
        }

        // Look back ~1 hour of ledgers (approximately 655 ledgers at 5.5s/ledger)
        // The RPC limits event lookback, so we use a reasonable window
        const startLedger = Math.max(1, latestLedger - 655);

        // Get existing entry keys so we can identify new ones
        const existingEntries = getEntriesForContract(db, contractId);
        const existingKeys = new Set(existingEntries.map(e => e.entry_key_xdr));

        // Fetch events for this contract with cursor-based pagination
        const allEvents: rpc.Api.EventResponse[] = [];
        let cursor: string | undefined;

        while (true) {
            const request: any = {
                filters: [
                    {
                        type: "contract",
                        contractIds: [contractId],
                    },
                ],
                limit: 100,
            };

            if (cursor) {
                request.pagination = { cursor };
            } else {
                request.startLedger = startLedger;
            }

            const page = await server.getEvents(request);
            if (page.events && page.events.length > 0) {
                allEvents.push(...page.events);
            }

            // Continue if there's a cursor for the next page
            if ((page as any).cursor && page.events && page.events.length === 100) {
                cursor = (page as any).cursor;
            } else {
                break;
            }
        }

        const txHashes = new Set<string>();
        for (const event of allEvents) {
            if (event.txHash) {
                txHashes.add(event.txHash);
            }
        }

        if (txHashes.size === 0) {
            logger.debug(`No events/transactions found for ${contractId} since ledger ${startLedger}`);
            return result;
        }

        result.transactionsScanned = txHashes.size;

        const rawContract = Buffer.from(contractId, "hex").length === 32
            ? Buffer.from(contractId, "hex")
            : decodeContractId(contractId);

        for (const txHash of txHashes) {
            try {
                const txResponse = await server.getTransaction(txHash) as any;
                if (!txResponse.envelopeXdr) {
                    continue; // Skip if no envelope
                }

                // Parse envelope
                // For mock compatibility, handle if envelopeXdr is already an object or a base64 string
                const env = typeof txResponse.envelopeXdr === 'string'
                    ? xdr.TransactionEnvelope.fromXDR(txResponse.envelopeXdr as string, "base64")
                    : txResponse.envelopeXdr;

                let innerTx;
                if (env.switch().name === 'envelopeTypeTx') {
                    innerTx = env.v1().tx();
                } else if (env.switch().name === 'envelopeTypeTxFeeBump') {
                    innerTx = env.feeBump().tx().innerTx().v1().tx();
                }

                if (!innerTx) continue;

                const ext = innerTx.ext();
                if (ext.switch().value !== 1) continue;

                const sorobanData = ext.v1().sorobanData();
                const footprint = sorobanData.resources().footprint();

                const keys = [...footprint.readOnly(), ...footprint.readWrite()];

                for (const key of keys) {
                    if (key.switch().name === 'contractData') {
                        const contractData = key.contractData();
                        const contractAddr = contractData.contract();
                        
                        // Check if key belongs to our contract
                        if (contractAddr.switch().name === 'scAddressTypeContract') {
                            const addrRaw = contractAddr.contractId();
                            
                            // Compare raw contract address
                            if (Buffer.compare(Buffer.from(addrRaw), Buffer.from(rawContract)) === 0) {
                                const keyXdr = key.toXDR("base64");
                                
                                if (!existingKeys.has(keyXdr)) {
                                    existingKeys.add(keyXdr);
                                    
                                    // Identify type (persistent, temporary, instance)
                                    let entryType = "persistent";
                                    if (contractData.durability().name === "temporary") entryType = "temporary";
                                    if (contractData.key().switch().name === "scvLedgerKeyContractInstance") entryType = "instance";
                                    
                                    upsertEntry(db, {
                                        contract_id: contractId,
                                        entry_key_xdr: keyXdr,
                                        entry_type: entryType,
                                        label: `Discovered (footprint)`,
                                        live_until_ledger: 0, // We could fetch from getLedgerEntries if we want TTL, but we can do that in a sync pass
                                        last_modified_ledger: 0,
                                        discovery_source: "footprint",
                                    });
                                    result.newKeysDiscovered++;
                                }
                            }
                        }
                    }
                }
            } catch (err) {
                logger.debug(`Failed to parse transaction footprint for ${contractId} (tx: ${txHash}): ${err}`);
            }
        }

        logger.debug(
            `Discovery for ${contractId}: scanned ${result.transactionsScanned} transactions, ` +
            `found ${result.newKeysDiscovered} new keys`,
        );
    } catch (err: unknown) {
        const message = err instanceof Error ? err.message : String(err);
        result.error = message;
        logger.error(`Discovery failed for ${contractId}: ${message}`, err);
    }

    return result;
}

/**
 * Run discovery for all registered contracts on a network.
 * Called by the daemon as an optional step after the monitor cycle.
 */
export async function runBatchDiscovery(
    db: Database.Database,
    network: string,
    rpcUrl?: string,
): Promise<BatchDiscoveryResult> {
    const batchResult: BatchDiscoveryResult = {
        contractsScanned: 0,
        totalNewKeys: 0,
        results: [],
        errors: [],
    };

    const contracts = getAllContracts(db).filter(c => c.network === network);

    for (const contract of contracts) {
        batchResult.contractsScanned++;

        try {
            const result = await discoverStorageKeys(db, contract.id, network, rpcUrl);
            batchResult.results.push(result);
            batchResult.totalNewKeys += result.newKeysDiscovered;

            if (result.error) {
                batchResult.errors.push(`${contract.id}: ${result.error}`);
            }
        } catch (err: unknown) {
            const message = err instanceof Error ? err.message : String(err);
            batchResult.errors.push(`${contract.id}: ${message}`);
        }
    }

    return batchResult;
}

// ─── Private helpers ──────────────────────────────────────────────────────────

/**
 * Decode a Stellar contract ID (C...) to raw 32-byte buffer.
 */
function decodeContractId(contractId: string): Buffer {
    try {
        return Buffer.from(StrKey.decodeContract(contractId));
    } catch {
        // Fallback: assume hex
        return Buffer.from(contractId, "hex");
    }
}

import type Database from "better-sqlite3";
import { StellarRpcClient } from "../rpc/client.js";
import {
    getAllContracts,
    getContract,
    getEntriesForContract,
    getExtensionPolicy,
    getChannelAccounts,
    recordExtension,
    upsertEntry,
    updateLastCheckedLedger,
    getAverageResourceUsage,
    getBudget,
    addBudgetSpent,
    countExtensionsInLastHour,

} from "../db/repositories.js";
import { ChannelAccountPool } from "./channels.js";
import { getLogger } from "../logging/index.js";
import { formatSecretKey } from "../utils/formatting.js";
import { resolveSecretKey } from "./secret_resolver.js";

const logger = getLogger().child({ component: "Extension" });


// ─── Rate limiter ─────────────────────────────────────────────────────────────

/**
 * Maximum number of auto-extension transactions allowed per contract per hour.
 * Prevents runaway fee submissions under extreme network load (issue #142).
 */
export const HOURLY_RATE_LIMIT = 5;

/**
 * Check whether the given contract has reached its hourly auto-extension rate limit.
 *
 * Queries `extension_history` for records within the last 60 minutes and
 * compares the count against `limit` (default: HOURLY_RATE_LIMIT).
 *
 * @param db - The SQLite database connection.
 * @param contractId - The contract to check.
 * @param limit - Maximum allowed extensions per hour (defaults to HOURLY_RATE_LIMIT).
 * @returns `true` when the contract is rate-limited; `false` otherwise.
 */
export function isRateLimited(
    db: import("better-sqlite3").Database,
    contractId: string,
    limit = HOURLY_RATE_LIMIT,
): boolean {
    const count = countExtensionsInLastHour(db, contractId);
    return count >= limit;
}

// ─── Public contract ──────────────────────────────────────────────────────────


export interface ExtensionResult {
    success: boolean;
    contractId: string;
    entriesExtended: number;
    txHash?: string;
    ledger?: number;
    error?: string;
    /** Estimated fee in stroops (from simulation, before submission). */
    estimatedFee?: number;
    /** Actual fee charged in stroops (from submitted transaction result). */
    feeCharged?: number;
    /** CPU instructions consumed by the transaction. */

    cpuInsns?: number;
    memBytes?: number;
    /** Read footprint size in bytes. */
    readBytes?: number;
    /** Write footprint size in bytes. */
    writeBytes?: number;
    /** Whether resource usage spiked. */

    isAnomaly?: boolean;
    anomalyDetails?: string;
}

export interface AutoExtensionResult {
    contractsChecked: number;
    contractsExtended: number;
    entriesExtended: number;
    errors: string[];
    extensions: Array<{
        contractId: string;
        txHash: string;
        entriesExtended: number;
        ledger: number;
        isAnomaly?: boolean;
        anomalyDetails?: string;
    }>;
}

export interface RestoreResult {
    success: boolean;
    contractId: string;
    entriesRestored: number;
    txHash?: string;
    ledger?: number;
    error?: string;
    /** Estimated fee in stroops (from simulation, before submission). */
    estimatedFee?: number;
    cpuInsns?: number;
    memBytes?: number;
    minResourceFee?: number;
    /** Fee charged in stroops. */
    feeCharged?: number;

}

export async function simulateExtension(
    db: Database.Database,
    contractId: string,
    entryKeyXdrs: string[],
    extendToLedgers: number,
    sourcePublicKey: string,
    rpcUrl?: string,
): Promise<ExtensionResult> {
    const contract = getContract(db, contractId);
    if (!contract) {
        return { success: false, contractId, entriesExtended: 0, error: "Contract not found" };
    }

    const client = new StellarRpcClient(contract.network, rpcUrl);

    let sim;
    try {
        sim = await client.simulateExtension(entryKeyXdrs, extendToLedgers, sourcePublicKey);
    } catch (err: any) {
        logger.warn(`Simulation warning for ${contractId}: ${err.message}`);
        return {
            success: false,
            contractId,
            entriesExtended: 0,
            error: err.message,
        };
    }

    return {
        success: true,
        contractId,
        entriesExtended: entryKeyXdrs.length,
        estimatedFee: sim.minResourceFee,
        cpuInsns: sim.cpuInstructions,
        memBytes: sim.memoryBytes,
        readBytes: sim.readBytes,
        writeBytes: sim.writeBytes,
    };
}

export async function extendEntries(
    db: Database.Database,
    contractId: string,
    entryKeyXdrs: string[],
    extendToLedgers: number,
    secretKey: string,
    rpcUrl?: string,
    sponsorSecret?: string,
): Promise<ExtensionResult> {
    const contract = getContract(db, contractId);
    if (!contract) {
        return { success: false, contractId, entriesExtended: 0, error: "Contract not found" };
    }

    if (entryKeyXdrs.length === 0) {
        return { success: false, contractId, entriesExtended: 0, error: "No entries to extend" };
    }

    const client = new StellarRpcClient(contract.network, rpcUrl);

    logger.info(
        `Extending ${entryKeyXdrs.length} entries for ${contractId} to ${extendToLedgers} ledgers`,
    );

    const resolvedSponsorSecret = sponsorSecret ? await resolveSecretKey(sponsorSecret) : undefined;
    if (sponsorSecret && !resolvedSponsorSecret) {
        return {
            success: false,
            contractId,
            entriesExtended: 0,
            error: `Failed to resolve sponsor secret key from environment variable: ${sponsorSecret}`,
        };
    }

    let txResult;
    try {
        txResult = resolvedSponsorSecret
            ? await client.submitExtensionWithFeeBump(
                entryKeyXdrs,
                extendToLedgers,
                secretKey,
                resolvedSponsorSecret,
            )
            : await client.submitExtension(entryKeyXdrs, extendToLedgers, secretKey);
    } catch (err: any) {
        logger.warn(`Simulation warning for ${contractId}: ${err.message}`);
        return {
            success: false,
            contractId,
            entriesExtended: 0,
            error: err.message,
        };
    }

    if (!txResult.success) {
        logger.error(`Extension failed for ${contractId}: ${txResult.error}`);
        return {
            success: false,
            contractId,
            entriesExtended: 0,
            txHash: txResult.txHash || undefined,
            error: txResult.error,
        };
    }

    let isAnomaly = false;
    let anomalyDetails: string | undefined = undefined;

    if (txResult.cpuInsns && txResult.memBytes) {
        const baseline = getAverageResourceUsage(db, contractId, 10);
        if (baseline && baseline.avg_cpu_insns > 0 && baseline.avg_mem_bytes > 0) {
            const cpuRatio = txResult.cpuInsns / baseline.avg_cpu_insns;
            const memRatio = txResult.memBytes / baseline.avg_mem_bytes;
            if (cpuRatio >= 2.0 || memRatio >= 2.0) {
                isAnomaly = true;
                const details = [];
                if (cpuRatio >= 2.0) details.push(`CPU usage is ${cpuRatio.toFixed(2)}x baseline`);
                if (memRatio >= 2.0) details.push(`Memory usage is ${memRatio.toFixed(2)}x baseline`);
                anomalyDetails = `Resource anomaly detected: ` + details.join(", ");
            }
        }
    }

    const freshTTLs = await client.getEntryTTLs(entryKeyXdrs);
    const entries = getEntriesForContract(db, contractId);
    const entryMap = new Map(entries.map(e => [e.entry_key_xdr, e]));

    const updateDb = db.transaction(() => {
        for (const freshEntry of freshTTLs.entries) {
            const dbEntry = entryMap.get(freshEntry.entryKeyXdr);
            if (!dbEntry) continue;

            const oldTTL = dbEntry.live_until_ledger
                ? dbEntry.live_until_ledger - freshTTLs.latestLedger
                : 0;

            recordExtension(db, {
                contract_id: contractId,
                contract_entry_id: dbEntry.id,
                old_ttl_ledgers: Math.max(0, oldTTL),
                new_ttl_ledgers: freshEntry.remainingTTL,
                tx_hash: txResult.txHash,
                cpu_insns: txResult.cpuInsns,
                mem_bytes: txResult.memBytes,
                is_anomaly: isAnomaly,
                executed_at_ledger: freshTTLs.latestLedger,
            });

            upsertEntry(db, {
                contract_id: contractId,
                entry_key_xdr: freshEntry.entryKeyXdr,
                entry_type: dbEntry.entry_type,
                label: dbEntry.label ?? undefined,
                live_until_ledger: freshEntry.liveUntilLedgerSeq,
                last_modified_ledger: freshEntry.lastModifiedLedgerSeq,
                discovery_source: dbEntry.discovery_source,
            });
        }

        updateLastCheckedLedger(db, contractId, freshTTLs.latestLedger);
    });
    updateDb();

    return {
        success: true,
        contractId,
        entriesExtended: entryKeyXdrs.length,
        txHash: txResult.txHash,
        ledger: txResult.ledger,
        feeCharged: txResult.feeCharged,
        cpuInsns: txResult.cpuInsns,
        memBytes: txResult.memBytes,
        isAnomaly,
        anomalyDetails,
    };
}

export async function runAutoExtensions(
    db: Database.Database,
    network: string,
    rpcUrl?: string,
    sponsorSecret?: string,
): Promise<AutoExtensionResult> {
    const result: AutoExtensionResult = {
        contractsChecked: 0,
        contractsExtended: 0,
        entriesExtended: 0,
        errors: [],
        extensions: [],
    };

    const contracts = getAllContracts(db).filter(c => c.network === network);

    const eligibleContracts = contracts.filter(c => {
        const p = getExtensionPolicy(db, c.id);
        return p && p.enabled;
    });

    if (eligibleContracts.length === 0) return result;

    const client = new StellarRpcClient(network, rpcUrl);
    const latestLedger = await client.getCurrentLedger();

    const channelAccounts = getChannelAccounts(db, network);
    const pool = channelAccounts.length > 0
        ? new ChannelAccountPool(db, network)
        : null;

    result.contractsChecked = eligibleContracts.length;

    await Promise.all(eligibleContracts.map(async contract => {
        const policy = getExtensionPolicy(db, contract.id)!;

        try {
            const entries = getEntriesForContract(db, contract.id);

            const needsExtension = entries.filter(e => {
                if (!e.live_until_ledger) return false;
                const remaining = e.live_until_ledger - latestLedger;
                return remaining >= 0 && remaining < policy.extend_when_below_ledgers;
            });

            if (needsExtension.length === 0) return;


            // ── Rate limit check (issue #142) ────────────────────────────────
            // Block auto-extension if the contract has already hit the maximum
            // number of extension transactions allowed per hour.
            if (isRateLimited(db, contract.id)) {
                const count = countExtensionsInLastHour(db, contract.id);
                const msg = `Contract ${contract.id}: rate limit reached — ${count}/${HOURLY_RATE_LIMIT} extensions in the last hour. Skipping.`;
                logger.warn(msg);
                result.errors.push(msg);
                return;
            }

            // Resolve secret key: prefer channel pool, fall back to policy keypair
            let secretKey: string | null = null;
            let slot: import("./channels.js").ChannelSlot | null = null;

            if (pool) {
                slot = await pool.acquire();
                secretKey = await resolveSecretKey(slot.keypairSource);
                if (!secretKey) {
                    pool.release(slot.publicKey);
                    slot = null;
                }
            }

            if (!secretKey) {
                secretKey = await resolveSecretKey(policy.keypair_source);
            }

            if (!secretKey) {
                result.errors.push(
                    `Contract ${contract.id}: Cannot resolve keypair from source "${pool ? "channel pool" : formatSecretKey(policy.keypair_source)}"`,
                );
                return;
            }

            const entryKeys = needsExtension.map(e => e.entry_key_xdr);

            logger.info(
                `Auto-extending ${entryKeys.length} entries for ${contract.id} ` +
                `(below ${policy.extend_when_below_ledgers}, target ${policy.target_ttl_ledgers})`,
            );

            try {
                const billingCycle = new Date().toISOString().slice(0, 7);
                const budget = getBudget(db, contract.id, billingCycle);
                let estimatedFeeXlm = 0;

                if (budget) {
                    const { Keypair } = await import("@stellar/stellar-sdk");
                    const pubKey = Keypair.fromSecret(secretKey).publicKey();
                    const simResult = await simulateExtension(db, contract.id, entryKeys, policy.target_ttl_ledgers, pubKey, rpcUrl);
                    
                    if (!simResult.success) {
                        throw new Error(`Simulation failed: ${simResult.error}`);
                    }
                    
                    estimatedFeeXlm = (simResult.estimatedFee || 0) / 10000000;
                    if (budget.spent_xlm + estimatedFeeXlm > budget.limit_xlm) {
                        throw new Error(`budget limit exceeded. Estimated cost: ${estimatedFeeXlm} XLM, Remaining: ${budget.limit_xlm - budget.spent_xlm} XLM`);
                    }
                }

                const extResult = await extendEntries(
                    db,
                    contract.id,
                    entryKeys,
                    policy.target_ttl_ledgers,
                    secretKey,
                    rpcUrl,
                    sponsorSecret,
                );

                if (extResult.success) {
                    if (budget && estimatedFeeXlm > 0) {
                        const actualFeeXlm = extResult.feeCharged !== undefined ? extResult.feeCharged / 10000000 : estimatedFeeXlm;
                        addBudgetSpent(db, contract.id, billingCycle, actualFeeXlm);
                    }

                    if (!extResult.txHash || extResult.ledger == null) {
                        result.errors.push(
                            `Contract ${contract.id}: Extension succeeded but RPC returned no txHash or ledger`,
                        );
                    } else {
                        result.contractsExtended++;
                        result.entriesExtended += extResult.entriesExtended;
                        result.extensions.push({
                            contractId: contract.id,
                            txHash: extResult.txHash,
                            entriesExtended: extResult.entriesExtended,
                            ledger: extResult.ledger,
                            isAnomaly: extResult.isAnomaly,
                            anomalyDetails: extResult.anomalyDetails,
                        });
                    }
                } else {
                    result.errors.push(
                        `Contract ${contract.id}: Extension failed — ${extResult.error}`,
                    );
                }
            } finally {
                if (slot && pool) pool.release(slot.publicKey);
            }
        } catch (err: unknown) {
            const message = err instanceof Error ? err.message : String(err);
            result.errors.push(`Contract ${contract.id}: ${message}`);
            logger.error(`Auto-extension error for ${contract.id}: ${message}`, err);
        }
    }));

    return result;
}

export async function simulateRestore(
    db: Database.Database,
    contractId: string,
    entryKeyXdrs: string[],
    sourcePublicKey: string,
    rpcUrl?: string,
): Promise<RestoreResult> {
    const contract = getContract(db, contractId);
    if (!contract) {
        return { success: false, contractId, entriesRestored: 0, error: "Contract not found" };
    }

    const client = new StellarRpcClient(contract.network, rpcUrl);
    const sim = await client.simulateRestore(entryKeyXdrs, sourcePublicKey);

    if (!sim.success) {
        return { success: false, contractId, entriesRestored: 0, error: sim.error };
    }

    return {
        success: true,
        contractId,
        entriesRestored: entryKeyXdrs.length,
        estimatedFee: sim.minResourceFee,
    };
}

export async function restoreEntries(
    db: Database.Database,
    contractId: string,
    entryKeyXdrs: string[],
    secretKey: string,
    rpcUrl?: string,
): Promise<RestoreResult> {
    const contract = getContract(db, contractId);
    if (!contract) {
        return { success: false, contractId, entriesRestored: 0, error: "Contract not found" };
    }

    if (entryKeyXdrs.length === 0) {
        return { success: false, contractId, entriesRestored: 0, error: "No entries to restore" };
    }

    const client = new StellarRpcClient(contract.network, rpcUrl);

    logger.info(`Restoring ${entryKeyXdrs.length} entries for ${contractId}`);

    let txResult;
    try {
        txResult = await client.submitRestore(entryKeyXdrs, secretKey);
    } catch (err: any) {
        logger.warn(`Simulation warning for ${contractId}: ${err.message}`);
        return {
            success: false,
            contractId,
            entriesRestored: 0,
            error: err.message,
        };
    }

    if (!txResult.success) {
        logger.error(`Restore failed for ${contractId}: ${txResult.error}`);
        return {
            success: false,
            contractId,
            entriesRestored: 0,
            txHash: txResult.txHash || undefined,
            error: txResult.error,
        };
    }

    const freshTTLs = await client.getEntryTTLs(entryKeyXdrs);
    const entries = getEntriesForContract(db, contractId);
    const entryMap = new Map(entries.map(e => [e.entry_key_xdr, e]));

    let restored = 0;

    const updateDb = db.transaction(() => {
        for (const freshEntry of freshTTLs.entries) {
            const dbEntry = entryMap.get(freshEntry.entryKeyXdr);
            if (!dbEntry) continue;

            upsertEntry(db, {
                contract_id: contractId,
                entry_key_xdr: freshEntry.entryKeyXdr,
                entry_type: dbEntry.entry_type,
                label: dbEntry.label ?? undefined,
                live_until_ledger: freshEntry.liveUntilLedgerSeq,
                last_modified_ledger: freshEntry.lastModifiedLedgerSeq,
                discovery_source: dbEntry.discovery_source,
            });
            restored++;
        }

        updateLastCheckedLedger(db, contractId, freshTTLs.latestLedger);
    });
    updateDb();

    logger.info(`Restore successful for ${contractId}: tx=${txResult.txHash}, entries=${restored}`);

    return {
        success: true,
        contractId,
        entriesRestored: restored,
        txHash: txResult.txHash,
        ledger: txResult.ledger,
        cpuInsns: txResult.cpuInsns,
        memBytes: txResult.memBytes,
        minResourceFee: txResult.minResourceFee,
        feeCharged: txResult.feeCharged,
    };
}

export { resolveSecretKey } from "./secret_resolver.js";

import type Database from "better-sqlite3";
import { xdr, Address, StrKey, scValToNative } from "@stellar/stellar-sdk";
import { getContract } from "../db/repositories.js";
import { StellarRpcClient } from "../rpc/client.js";
import { classifyTTL, formatTimeToCloseLedger, formatContractID } from "../utils/formatting.js";
import { getLogger } from "../logging/index.js";

const logger = getLogger().child({ component: "InspectCore" });

export interface InspectOptions {
    entries?: string[];
    network?: string;
    rpcUrl?: string;
}

export interface DecodedScVal {
    type: string;
    value: any;
}

export interface InspectEntryInfo {
    inputEntry: string;
    entryKeyXdr: string;
    type: "balance" | "raw";
    found: boolean;
    remainingTTL?: number | null;
    approximateTimeRemaining?: string | null;
    status?: string;
    balance?: {
        amount: bigint;
        authorized: boolean;
        clawback: boolean;
    };
    formattedBalance?: string;
    decodedValue?: DecodedScVal;
}

export interface InspectResult {
    success: boolean;
    contractId: string;
    contractName?: string | null;
    network?: string;
    isSac?: boolean;
    decimals?: number;
    results?: InspectEntryInfo[];
    error?: string;
}

/**
 * Format token balance in stroops/raw units to string representation with decimals.
 */
export function formatTokenBalance(amount: bigint | number | string, decimals: number): string {
    const bigAmount = BigInt(amount);
    const isNegative = bigAmount < 0n;
    const absAmount = isNegative ? -bigAmount : bigAmount;
    const divisor = 10n ** BigInt(decimals);
    const integerPart = absAmount / divisor;
    const remainder = absAmount % divisor;

    let result = integerPart.toString();
    if (decimals > 0) {
        const remainderStr = remainder.toString().padStart(decimals, "0");
        const trimmedRemainder = remainderStr.replace(/0+$/, "");
        if (trimmedRemainder.length > 0) {
            result += "." + trimmedRemainder;
        }
    }
    return isNegative ? "-" + result : result;
}

/**
 * Custom parser for SAC balance map layout.
 */
export function parseSacBalance(scVal: xdr.ScVal | string): { amount: bigint; authorized: boolean; clawback: boolean } {
    let valObj: xdr.ScVal;
    if (typeof scVal === "string") {
        try {
            valObj = xdr.ScVal.fromXDR(scVal, "base64");
        } catch {
            throw new Error("Invalid SAC balance map layout");
        }
    } else {
        valObj = scVal;
    }

    if (!valObj || typeof valObj.switch !== "function" || valObj.switch().name !== "scvMap") {
        throw new Error("Invalid SAC balance map layout");
    }

    let native: any;
    try {
        native = scValToNative(valObj);
    } catch {
        throw new Error("Invalid SAC balance map layout");
    }

    if (!native || typeof native !== "object" || native.amount === undefined) {
        throw new Error("Invalid SAC balance map layout");
    }

    return {
        amount: BigInt(native.amount),
        authorized: Boolean(native.authorized ?? true),
        clawback: Boolean(native.clawback ?? false),
    };
}

/**
 * Build storage key XDR for a SAC address balance entry.
 */
export function buildSacBalanceKeyXdr(contractId: string, address: string): string {
    const addr = Address.fromString(address);
    const keyVal = xdr.ScVal.scvVec([
        xdr.ScVal.scvSymbol("Balance"),
        addr.toScVal(),
    ]);

    const raw = Buffer.from(contractId, "hex").length === 32
        ? Buffer.from(contractId, "hex")
        : Buffer.from(StrKey.decodeContract(contractId));

    const contractAddress = xdr.ScAddress.scAddressTypeContract(
        raw as unknown as xdr.Hash,
    );

    const ledgerKey = xdr.LedgerKey.contractData(
        new xdr.LedgerKeyContractData({
            contract: contractAddress,
            key: keyVal,
            durability: xdr.ContractDataDurability.persistent(),
        }),
    );

    return ledgerKey.toXDR("base64");
}

/**
 * Inspect contract storage and token balances on SAC contracts.
 */
export async function inspectContract(
    db: Database.Database,
    contractId: string,
    options: InspectOptions = {},
): Promise<InspectResult> {
    let contract: { name?: string | null; network: string; rpc_url?: string | null } | null | undefined = null;
    try {
        contract = getContract(db, contractId);
    } catch {
        // DB not initialized or not found
    }

    const network = contract?.network ?? options.network ?? "testnet";
    const rpcUrl = contract?.rpc_url ?? options.rpcUrl;
    const contractName = contract?.name ?? null;

    const client = new StellarRpcClient(network, rpcUrl ?? undefined);

    // 1. Check if SAC contract
    const instance = await client.getContractInstanceEntry(contractId);
    if (!instance) {
        return {
            success: false,
            contractId,
            error: `Contract instance not found on-chain for ${formatContractID(contractId)}.`,
        };
    }

    const isSac = instance.executableType === "contractExecutableStellarAsset";

    // 2. Fetch SAC decimals (only if SAC)
    const decimals = isSac ? await client.getSacDecimals(contractId) : 0;

    // 3. Process entries
    const inputEntries = options.entries ?? [];
    if (inputEntries.length === 0) {
        return {
            success: true,
            contractId,
            contractName,
            network,
            isSac,
            decimals,
            results: [],
        };
    }

    const mapped: { inputEntry: string; entryKeyXdr: string; type: "balance" | "raw" }[] = [];

    for (const inputEntry of inputEntries) {
        if (inputEntry.startsWith("balance:")) {
            if (!isSac) {
                return {
                    success: false,
                    contractId,
                    error: `Contract ${formatContractID(contractId)} is not a standard Stellar Asset Contract (SAC). Cannot inspect balance slots.`,
                };
            }
            const address = inputEntry.slice("balance:".length).trim();
            try {
                const keyXdr = buildSacBalanceKeyXdr(contractId, address);
                mapped.push({ inputEntry, entryKeyXdr: keyXdr, type: "balance" });
            } catch (err: any) {
                return {
                    success: false,
                    contractId,
                    error: `Failed to locate balance slot for address "${address}": ${err.message ?? String(err)}`,
                };
            }
        } else {
            mapped.push({ inputEntry, entryKeyXdr: inputEntry, type: "raw" });
        }
    }

    const keyXdrs = mapped.map(m => m.entryKeyXdr);
    const storageEntries = await client.getContractStorageEntries(keyXdrs);
    const entryMap = new Map(storageEntries.map(e => [e.entryKeyXdr, e]));

    const results: InspectEntryInfo[] = mapped.map(item => {
        const foundEntry = entryMap.get(item.entryKeyXdr);
        if (!foundEntry || !foundEntry.valXdr) {
            if (item.type === "balance") {
                return {
                    inputEntry: item.inputEntry,
                    entryKeyXdr: item.entryKeyXdr,
                    type: "balance",
                    found: false,
                    remainingTTL: null,
                    approximateTimeRemaining: null,
                    status: "unknown",
                    balance: { amount: 0n, authorized: true, clawback: false },
                    formattedBalance: formatTokenBalance(0n, decimals),
                };
            } else {
                return {
                    inputEntry: item.inputEntry,
                    entryKeyXdr: item.entryKeyXdr,
                    type: "raw",
                    found: false,
                    remainingTTL: null,
                    approximateTimeRemaining: null,
                    status: "unknown",
                };
            }
        }

        const remTTL = foundEntry.remainingTTL;
        const ttlStatus = classifyTTL(remTTL);
        const approxTime = formatTimeToCloseLedger(remTTL);

        if (item.type === "balance") {
            let bal = { amount: 0n, authorized: true, clawback: false };
            try {
                bal = parseSacBalance(foundEntry.valXdr);
            } catch {
                logger.debug("Failed to decode balance valXdr", { valXdr: foundEntry.valXdr });
            }
            return {
                inputEntry: item.inputEntry,
                entryKeyXdr: item.entryKeyXdr,
                type: "balance",
                found: true,
                remainingTTL: remTTL,
                approximateTimeRemaining: approxTime,
                status: ttlStatus,
                balance: bal,
                formattedBalance: formatTokenBalance(bal.amount, decimals),
            };
        } else {
            let decodedValue: DecodedScVal | undefined;
            if (foundEntry.valXdr) {
                decodedValue = decodeScVal(foundEntry.valXdr);
            }
            return {
                inputEntry: item.inputEntry,
                entryKeyXdr: item.entryKeyXdr,
                type: "raw",
                found: true,
                remainingTTL: remTTL,
                approximateTimeRemaining: approxTime,
                status: ttlStatus,
                decodedValue,
            };
        }
    });

    return {
        success: true,
        contractId,
        contractName,
        network,
        isSac,
        decimals,
        results,
    };
}

/**
 * Decode a base64 XDR ScVal string into a JSON-friendly structure.
 */
export function decodeScVal(scValBase64: string): DecodedScVal {
    try {
        const scVal = xdr.ScVal.fromXDR(scValBase64, "base64");
        return decodeScValRecursive(scVal);
    } catch (e: any) {
        return { type: "error", value: `Failed to decode ScVal: ${e.message}` };
    }
}

function decodeScValRecursive(scVal: xdr.ScVal): DecodedScVal {
    const type = scVal.switch().name;
    let value: any;

    switch (type) {
        case "scvU32":
        case "scvI32":
            value = scVal.value();
            break;
        case "scvBool":
            value = scVal.b();
            break;
        case "scvString":
        case "scvSymbol":
            value = scVal.value()?.toString() ?? null;
            break;
        case "scvU64":
        case "scvI64":
        case "scvU128":
        case "scvI128":
        case "scvU256":
        case "scvI256":
            try {
                value = scValToNative(scVal).toString();
            } catch {
                value = "<unsupported bigint>";
            }
            break;
        case "scvMap":
            value = (scVal.map() ?? []).map((entry) => ({
                key: decodeScValRecursive(entry.key()),
                value: decodeScValRecursive(entry.val()),
            }));
            break;
        case "scvVec":
            value = (scVal.vec() ?? []).map((val) => decodeScValRecursive(val));
            break;
        case "scvBytes":
            value = scVal.bytes().toString("hex");
            break;
        case "scvAddress":
            try {
                value = scValToNative(scVal);
            } catch {
                value = "<address>";
            }
            break;
        case "scvVoid":
            value = null;
            break;
        default:
            try {
                value = scValToNative(scVal);
            } catch {
                value = `<native conversion failed for ${type}>`;
            }
    }

    return { type, value };
}

import { xdr, scValToNative } from "@stellar/stellar-sdk";

/**
 * Translate a Soroban `SCVal` into a JSON-safe representation.
 *
 * Design goals:
 * - Recursively translate nested vectors/maps.
 * - Avoid precision loss: large ints are always returned as strings.
 * - Produce human-readable tokens for symbol/address.
 */
export function scvalToJSON(val: xdr.ScVal): any {
  let native;
  try {
    native = scValToNative(val);
  } catch (e) {
    return { unsupported: val.switch().name };
  }
  return serializeBigInts(native);
}

function serializeBigInts(obj: any): any {
  if (typeof obj === "bigint") {
    return obj.toString(10);
  }
  if (Array.isArray(obj)) {
    return obj.map(serializeBigInts);
  }
  if (obj !== null && typeof obj === "object") {
    const res: any = {};
    for (const [k, v] of Object.entries(obj)) {
      res[k] = serializeBigInts(v);
    }
    return res;
  }
  return obj;
}

/* eslint-disable @typescript-eslint/no-unused-vars */
import { getLogger } from "../logging/index.js";

const logger = getLogger().child({ component: "VaultResolver" });

export interface VaultConfig {
    url: string;
    token: string;
    namespace?: string;
}

export class VaultAuthError extends Error {
    constructor(message: string = "Vault authentication failed") {
        super(message);
        this.name = "VaultAuthError";
    }
}

export class VaultSecretNotFoundError extends Error {
    constructor(secretPath: string) {
        super(`Secret not found in Vault at path: ${secretPath}`);
        this.name = "VaultSecretNotFoundError";
    }
}

export class VaultSecretError extends Error {
    constructor(message: string) {
        super(message);
        this.name = "VaultSecretError";
    }
}

/**
 * VaultResolver - Retrieve Stellar secret keys dynamically from HashiCorp Vault
 *
 * Supports KV v1 and KV v2 secret engines.
 *
 * Secret lookup order for field names:
 *   secret_key, private_key, secret, value, stellar_secret, key
 *
 * You can also specify a custom field with a fragment: vault:secret/data/foo#my_field
 */
export class VaultResolver {
    private url: string;
    private token: string;
    private namespace?: string;

    constructor(config: VaultConfig) {
        if (!config.url) {
            throw new VaultSecretError("Vault URL is required");
        }
        if (!config.token) {
            throw new VaultAuthError("Vault token is required");
        }
        // Normalize URL (strip trailing slash)
        this.url = config.url.replace(/\/$/, "");
        this.token = config.token;
        this.namespace = config.namespace;
    }

    /**
     * Fetch a Stellar secret key from Vault
     * @param secretPath Vault secret path, optionally with #field suffix
     * @returns Stellar secret key string (starts with S)
     */
    async getSecret(secretPath: string): Promise<string> {
        // Parse field fragment
        let path = secretPath;
        let fieldName: string | null = null;

        const hashIdx = secretPath.indexOf("#");
        if (hashIdx !== -1) {
            path = secretPath.slice(0, hashIdx);
            fieldName = secretPath.slice(hashIdx + 1);
        }

        // Strip leading slash
        if (path.startsWith("/")) {
            path = path.slice(1);
        }

        const url = `${this.url}/v1/${path}`;

        const headers: Record<string, string> = {
            "X-Vault-Token": this.token,
            "Accept": "application/json",
        };

        if (this.namespace) {
            headers["X-Vault-Namespace"] = this.namespace;
        }

        let res: Response;
        try {
            res = await fetch(url, { headers });
        } catch (err) {
            const message = err instanceof Error ? err.message : String(err);
            logger.error(`Vault request failed: ${message}`);
            throw new VaultSecretError(`Vault request failed: ${message}`);
        }

        if (!res.ok) {
            if (res.status === 403 || res.status === 401) {
                throw new VaultAuthError(`Vault authentication failed (${res.status})`);
            }
            if (res.status === 404) {
                throw new VaultSecretNotFoundError(path);
            }
            let body = "";
            try {
                body = await res.text();
            } catch { /* ignore */ }
            throw new VaultSecretError(`Vault request failed with status ${res.status}: ${body}`);
        }

        let json: any;
        try {
            json = await res.json();
        } catch (err) {
            throw new VaultSecretError("Failed to parse Vault response as JSON");
        }

        // KV v2: data.data.{field}
        // KV v1: data.{field}
        let secretData: Record<string, any> | undefined;
        if (json?.data?.data && typeof json.data.data === "object") {
            secretData = json.data.data;
        } else if (json?.data && typeof json.data === "object") {
            secretData = json.data;
        }

        if (!secretData) {
            throw new VaultSecretError(`No secret data found at Vault path: ${path}`);
        }

        let secretValue: string | undefined;

        if (fieldName) {
            secretValue = secretData[fieldName];
            if (secretValue === undefined) {
                throw new VaultSecretError(
                    `Field '${fieldName}' not found in Vault secret at path: ${path}`
                );
            }
        } else {
            // Try common field names in order
            const candidates = [
                "secret_key",
                "private_key",
                "secret",
                "value",
                "stellar_secret",
                "key",
            ];
            for (const key of candidates) {
                if (typeof secretData[key] === "string") {
                    secretValue = secretData[key];
                    break;
                }
            }

            // Fallback: if there's exactly one string field that looks like a Stellar secret, use it
            if (!secretValue) {
                const stringEntries = Object.entries(secretData).filter(
                    ([, v]) => typeof v === "string"
                ) as [string, string][];
                if (stringEntries.length === 1) {
                    const first = stringEntries[0];
                    if (first) secretValue = first[1];
                } else {
                    // Try to find any Stellar-looking secret
                    const stellarEntry = stringEntries.find(([, v]) => isStellarSecret(v));
                    if (stellarEntry) {
                        secretValue = stellarEntry[1];
                    }
                }
            }
        }

        if (!secretValue || typeof secretValue !== "string") {
            throw new VaultSecretError(
                `No valid secret key found in Vault response at path: ${path}. ` +
                `Expected one of: secret_key, private_key, secret, value, stellar_secret, key`
            );
        }

        if (!isStellarSecret(secretValue)) {
            throw new VaultSecretError(
                `Secret retrieved from Vault is not a valid Stellar secret key format. ` +
                `Expected 56-character string starting with 'S', got: ${maskSecret(secretValue)}`
            );
        }

        logger.debug(`Successfully resolved secret from Vault path: ${path}`);
        return secretValue;
    }
}

/**
 * Check if a string looks like a Stellar secret key
 */
function isStellarSecret(value: string): boolean {
    return typeof value === "string" && value.startsWith("S") && value.length === 56;
}

function maskSecret(secret: string): string {
    if (secret.length <= 8) return "***";
    return `${secret.slice(0, 4)}...${secret.slice(-4)}`;
}

import type Database from "better-sqlite3";
import { StellarRpcClient, ContractInstanceResult, SorokeepLedgerEntryResult } from "../rpc/client.js";
import {
    insertContract,
    upsertEntry,
    updateLastCheckedLedger,
    getContract,
    updateLastIntrospectedAt,
    isIntrospectionCacheValid,
} from "../db/repositories.js";
import {getLogger} from "../logging/index.js";

const logger = getLogger()

export interface WatchOptions {
    contractId: string;
    network: string;
    name?: string;
    rpcUrl?: string;
    storageKeys?: string[];
    pollIntervalSeconds?: number;
    /**
     * When true, skip the introspection cache and always fetch fresh data from
     * the RPC. Useful for manual `watch` commands where the user expects an
     * immediate refresh.  Defaults to false.
     */
    forceRefresh?: boolean;
    noIntrospection?: boolean;
}

export type WatchResult =
    | {
    success: true;
    contractId: string;
    instance: ContractInstanceResult;
    wasm: SorokeepLedgerEntryResult | null;
    wasmWarning?: string;
    /** True when the result was served from the introspection cache (no RPC call). */
    fromCache?: boolean;
} | {
    success: false;
    contractId: string;
    error: string;
};

/**
 * Core logic to discover and register a contract and its key entries.
 * - This is `Layer 1` of the architecture.
 */
export async function watchContract(db: Database.Database, options: WatchOptions): Promise<WatchResult> {
    logger.debug(`Watching contract ${options.contractId} on ${options.network}`);
    const { contractId, network, name, rpcUrl, storageKeys, forceRefresh = false, pollIntervalSeconds } = options;

    // Basic Validation
    if (!contractId.startsWith("C") || contractId.length !== 56) {
        logger.error(`Invalid Contract ID format: ${contractId}`);
        return {
            success: false,
            contractId,
            error: "Invalid Contract ID format. Must be a 56-character string starting with 'C'.",
        };
    }

    const client = new StellarRpcClient(network, rpcUrl);

    try {
        // 0. Check if already registered on a different network
        const existing = getContract(db, contractId);
        if (existing && existing.network !== network) {
            logger.warn(`Contract ${contractId} is already registered on ${existing.network}. To watch on ${network}, unwatch it first.`);
            return {
                success: false,
                contractId,
                error: `Contract ${contractId} is already registered on ${existing.network}. To watch on ${network}, unwatch it first.`,
            };
        }

        // ── Introspection cache check ─────────────────────────────────────────
        // If the contract has been introspected recently (within 24 h) and the
        // caller did not request a forced refresh, skip the RPC calls entirely
        // and return the cached result.
        if (!forceRefresh && isIntrospectionCacheValid(db, contractId)) {
            logger.debug(`Contract ${contractId}: introspection cache is valid — skipping RPC calls`);

            // Build a minimal success result from cached DB data.
            // We return success=true without real instance/wasm objects so that
            // callers (CLI, daemon) know the operation succeeded. The actual
            // entry data remains accurate in the DB from the last introspection.
            return {
                success: true,
                contractId,
                // Provide stub values — callers that need live RPC data should
                // use forceRefresh=true.
                instance: {
                    entryKeyXdr: "",
                    latestLedger: 0,
                    liveUntilLedgerSeq: 0,
                    lastModifiedLedgerSeq: 0,
                    remainingTTL: 0,
                    executableType: "cached",
                    wasmHash: existing?.wasm_hash ?? null,
                },
                wasm: null,
                fromCache: true,
            };
        }

        // 1. Fetch Contract Instance Entry
        const instanceEntry = await client.getContractInstanceEntry(contractId);
        if (!instanceEntry) {
            return {
                success: false,
                contractId,
                error: `Contract ${contractId} not found on ${network}.`,
            };
        }

        // 2. Fetch WASM code entry if applicable
        let wasmEntry: SorokeepLedgerEntryResult | null = null;
        let wasmWarning: string | undefined;

        if (instanceEntry.wasmHash && !options.noIntrospection) {
            wasmEntry = await client.getWasmCodeEntry(instanceEntry.wasmHash);
            if (!wasmEntry) {
                wasmWarning = `WASM entry for hash ${instanceEntry.wasmHash} not found. It might be archived.`;
            }
        }

        // 3. Fetch Manual Storage Keys if provided
        const extraEntries: SorokeepLedgerEntryResult[] = [];
        if (storageKeys && storageKeys.length > 0) {
            const ttls = await client.getEntryTTLs(storageKeys);
            extraEntries.push(...ttls.entries);
        }

        // 3.5. Introspection: Fetch monitored keys if contract supports it
        const introspectedEntries: SorokeepLedgerEntryResult[] = [];
        if (!options.noIntrospection) {
            try {
                const keys = await client.getMonitoredKeys(contractId);
                if (keys.length > 0) {
                    const ttls = await client.getEntryTTLs(keys);
                    introspectedEntries.push(...ttls.entries);
                }
            } catch (error) {
                logger.debug(`Introspection skipped for ${contractId}: ${error}`);
            }
        }

        // 4. Store in Database
        // Note: insertContract uses ON CONFLICT(id) DO UPDATE
        insertContract(db, {
            id: contractId,
            name: name,
            network: network,
            wasm_hash: instanceEntry.wasmHash ?? undefined,
            poll_interval_seconds: pollIntervalSeconds ?? null,
        });

        // Store Instance Entry
        upsertEntry(db, {
            contract_id: contractId,
            entry_key_xdr: instanceEntry.entryKeyXdr,
            entry_type: "instance",
            label: "Contract Instance",
            live_until_ledger: instanceEntry.liveUntilLedgerSeq,
            last_modified_ledger: instanceEntry.lastModifiedLedgerSeq,
            discovery_source: "deterministic",
        });

        // Store WASM Entry if found
        if (wasmEntry) {
            upsertEntry(db, {
                contract_id: contractId,
                entry_key_xdr: wasmEntry.entryKeyXdr,
                entry_type: "wasm",
                label: "WASM Code",
                live_until_ledger: wasmEntry.liveUntilLedgerSeq,
                last_modified_ledger: wasmEntry.lastModifiedLedgerSeq,
                discovery_source: "deterministic",
            });
        }

        // Store Manual Storage Entries
        for (const entry of extraEntries) {
            upsertEntry(db, {
                contract_id: contractId,
                entry_key_xdr: entry.entryKeyXdr,
                entry_type: "persistent", // Defaulting to persistent for manual keys
                label: "Manual Storage Entry",
                live_until_ledger: entry.liveUntilLedgerSeq,
                last_modified_ledger: entry.lastModifiedLedgerSeq,
                discovery_source: "manual",
            });
        }

        // Store Introspected Entries
        for (const entry of introspectedEntries) {
            upsertEntry(db, {
                contract_id: contractId,
                entry_key_xdr: entry.entryKeyXdr,
                entry_type: "persistent", // Defaulting to persistent for introspected keys
                label: "Introspected Storage Entry",
                live_until_ledger: entry.liveUntilLedgerSeq,
                last_modified_ledger: entry.lastModifiedLedgerSeq,
                discovery_source: "introspection",
            });
        }

        // Update last checked ledger
        updateLastCheckedLedger(db, contractId, instanceEntry.latestLedger);

        // ── Record successful introspection in the cache ───────────────────────
        updateLastIntrospectedAt(db, contractId, new Date().toISOString());

        return {
            success: true,
            contractId,
            instance: instanceEntry,
            wasm: wasmEntry,
            wasmWarning,
            fromCache: false,
        };

    } catch (error: any) {
        logger.error(`Error watching contract ${contractId}: ${error.message}`, error);
        return {
            success: false,
            contractId,
            error: error.message,
        };
    }
}

import {
    Contract,
    rpc,
    xdr,
    TransactionBuilder,
    Networks,
    Account,
    Operation,
    Keypair,
    SorobanDataBuilder,
    FeeBumpTransaction,
    Asset,
} from "@stellar/stellar-sdk";
import { getLogger } from "../logging/index.js";
// CostSummary removed — no longer exported from costs.js

export function assertSimulationSuccess(sim: rpc.Api.SimulateTransactionResponse): asserts sim is rpc.Api.SimulateTransactionSuccessResponse {
    if (rpc.Api.isSimulationError(sim)) {
        if (sim.error?.includes("txBadSeq")) {
            throw new Error("Simulation failed: Expired sequence number");
        }
        if (sim.error?.includes("txInsufficientBalance")) {
            throw new Error("Simulation failed: Insufficient wallet balance");
        }
        if (sim.error?.includes("invalid footprint")) {
            throw new Error("Simulation failed: Invalid footprint key");
        }
        throw new Error(`Simulation failed: ${sim.error ?? "unknown error"}`);
    }
    
    // Handle cases where error field exists but may be null/undefined
    const simAny = sim as any;
    if ("error" in simAny) {
        throw new Error(`Simulation failed: ${simAny.error ?? "unknown error"}`);
    }
}


/**
 * Executes an RPC action with exponential backoff on network timeouts or 429/5xx errors.
 * Starts at 1 second, doubling up to 3 retries (max 4 attempts).
 */
export async function executeWithRetry<T>(action: () => Promise<T>): Promise<T> {
    const MAX_RETRIES = 3;
    let delayMs = 1000;

    for (let attempt = 0; attempt <= MAX_RETRIES; attempt++) {
        try {
            return await action();
        } catch (error: any) {
            const isTimeout = error?.code === "ETIMEDOUT" || error?.code === "ECONNRESET" || error?.message?.includes("timeout");
            const status = error?.response?.status;
            const isRetryableHttp = status === 429 || (status >= 500 && status < 600);

            if ((isTimeout || isRetryableHttp) && attempt < MAX_RETRIES) {
                await new Promise(resolve => setTimeout(resolve, delayMs));
                delayMs *= 2;
                continue;
            }

            throw error;
        }
    }
    throw new Error("Unreachable");
}

const logger = getLogger().child({ component: "StellarRpcClient" });

const RPC_URLS: Record<string, string> = {
    testnet: "https://soroban-testnet.stellar.org",
    mainnet: "https://mainnet.sorobanrpc.com",
};

export interface SorokeepLedgerEntryResult {
    entryKeyXdr: string;
    latestLedger: number;
    liveUntilLedgerSeq: number;
    lastModifiedLedgerSeq: number;
    remainingTTL: number;
}

export interface ContractInstanceResult extends SorokeepLedgerEntryResult {
    executableType: string;
    wasmHash: string | null;
}

export interface EntryTTLsResult {
    latestLedger: number;
    entries: SorokeepLedgerEntryResult[];
}

export interface ContractStorageEntryResult extends SorokeepLedgerEntryResult {
    valXdr?: string;
}

export interface SimulateExtensionResult {
    minResourceFee: number;
    success: boolean;
    error?: string;
    /** CPU instructions consumed by the transaction. */
    cpuInstructions?: number;
    /** Memory bytes consumed by the transaction. */
    memoryBytes?: number;
    /** Read footprint size in bytes. */
    readBytes?: number;
    /** Write footprint size in bytes. */
    writeBytes?: number;
}

/**
 * Structured resource usage estimate extracted from a simulateTransaction response.
 * Used for budget safety checks before executing auto-extensions (issue #133).
 */
export interface ResourceEstimate {
    /** CPU instructions estimated for the transaction. */
    cpuInstructions: number;
    /** Memory bytes estimated for the transaction. */
    memoryBytes: number;
    /** Minimum resource fee in stroops estimated by the RPC node. */
    minResourceFee: number;
}

/**
 * Parse a simulateTransaction RPC response into a structured ResourceEstimate.
 *
 * Extracts `cpuInstructions` from `response.cost.cpuInsns`,
 * `memoryBytes` from `response.cost.memBytes`, and
 * `minResourceFee` from `response.minResourceFee`.
 *
 * Returns `null` when:
 *   - The input is null, undefined, or not a plain object.
 *   - The response contains an `error` field (simulation failed).
 *   - Neither `cost` nor `minResourceFee` fields are present.
 *
 * Missing numeric fields default to `0` rather than `NaN`.
 *
 * @param response - The raw simulation response object (or null/undefined).
 * @returns A ResourceEstimate on success, or null on failure.
 */
export function parseResourceEstimate(response: unknown): ResourceEstimate | null {
    if (response === null || response === undefined) return null;
    if (typeof response !== "object" || Array.isArray(response)) return null;

    const sim = response as Record<string, unknown>;

    // Simulation error responses have an `error` field — always return null.
    if (typeof sim["error"] === "string") return null;

    // Need at least one field present (even if null) to return a meaningful estimate.
    const hasCostField = "cost" in sim;
    const hasFeeField = "minResourceFee" in sim;
    if (!hasCostField && !hasFeeField) return null;

    // Parse minResourceFee (may be a string or number in the Soroban RPC response)
    const rawFee = sim["minResourceFee"];
    const minResourceFee = rawFee !== undefined && rawFee !== null
        ? safeParseNumber(rawFee)
        : 0;

    // Parse cost fields
    let cpuInstructions = 0;
    let memoryBytes = 0;

    const cost = sim["cost"];
    if (cost !== undefined && cost !== null && typeof cost === "object" && !Array.isArray(cost)) {
        const costObj = cost as Record<string, unknown>;
        cpuInstructions = safeParseNumber(costObj["cpuInsns"]);
        memoryBytes = safeParseNumber(costObj["memBytes"]);
    }

    return { cpuInstructions, memoryBytes, minResourceFee };
}

/** Parse a value to a non-negative finite integer, defaulting to 0. */
export function safeParseNumber(value: unknown): number {
    if (value === undefined || value === null) return 0;
    const n = typeof value === "number" ? value : Number(value);
    return Number.isFinite(n) && n >= 0 ? Math.floor(n) : 0;
}

export interface FeeStatsResult {
    latestLedger?: number;
    baseFeeStroops: number;
    surgeFeeStroops: number;
    surgePricingMultiplier: number;
}

export interface SubmitTransactionResult {
    success: boolean;
    txHash: string;
    ledger: number;
    cpuInsns?: number;
    memBytes?: number;
    error?: string;
    cpuInstructions?: number;
    memoryBytes?: number;
    minResourceFee?: number;
    /** Actual fee charged in stroops, parsed from the transaction result. */
    feeCharged?: number;
}

export function extractResourceCosts(resultMetaXdrBase64: string): { cpuInstructions: number, memoryBytes: number } | null {
    if (!resultMetaXdrBase64) return null;
    try {
        const meta = xdr.TransactionMeta.fromXDR(resultMetaXdrBase64, "base64");
        const v3 = typeof meta.v3 === 'function' ? meta.v3() : undefined;
        
        if (v3) {
            const sorobanMeta = typeof v3.sorobanMeta === 'function' ? v3.sorobanMeta() : undefined;
            if (sorobanMeta) {
                const anyMeta = sorobanMeta as any;
                const cpuInstructions = typeof anyMeta.cpuInstructions === 'function' ? Number(anyMeta.cpuInstructions()) : undefined;
                const memoryBytes = typeof anyMeta.memoryBytes === 'function' ? Number(anyMeta.memoryBytes()) : undefined;

                if (cpuInstructions !== undefined && memoryBytes !== undefined) {
                    return { cpuInstructions, memoryBytes };
                }
            }
        }
    } catch (error) {
        logger.debug("Failed to decode resultMetaXdr for resource costs", { error: String(error) });
    }
    return null;
}

const NETWORK_PASSPHRASES: Record<string, string> = {
    testnet: Networks.TESTNET,
    mainnet: Networks.PUBLIC,
};

export interface StellarRpcClientOptions {
    maxRequestsPerSecond?: number;
}

export class StellarRpcClient {
    private readonly network: string;
    private readonly server: rpc.Server;
    private readonly maxRequestsPerSecond: number;
    private readonly requestIntervalMs: number;
    private recentRequestTimes: number[] = [];

    constructor(network: string, customUrl?: string, options: StellarRpcClientOptions = {}) {
        this.network = network;
        const configured = options.maxRequestsPerSecond ?? 5;
        this.maxRequestsPerSecond = configured > 0 ? configured : 5;
        this.requestIntervalMs = Math.ceil(1000 / this.maxRequestsPerSecond);
        const url = customUrl ?? RPC_URLS[network];
        if (!url) {
            throw new Error(`Unknown network "${network}". Use "testnet", "mainnet", or provide a custom URL.`);
        }
        this.server = new rpc.Server(url, { allowHttp: url.startsWith("http://") });
    }

    getNetwork(): string {
        return this.network;
    }

    async checkHealth() {
        return await this.withRateLimit(() => this.server.getHealth());
    }

    async getCurrentLedger(): Promise<number> {
        const serverAny = this.server as any;
        if (typeof serverAny.getLatestLedger === "function") {
            try {
                const response = await this.withRateLimit(() => serverAny.getLatestLedger());
                const seq = (response as any)?.sequence;
                if (typeof seq === "number" && seq > 0) return seq;
            } catch (error) {
                logger.debug("getLatestLedger failed, falling back to getHealth", error);
            }
        }

        const health = await this.withRateLimit(() => this.server.getHealth());
        if (health && typeof (health as any).latestLedger === "number") {
            return (health as any).latestLedger;
        }

        throw new Error("Unable to determine latest ledger from RPC server");
    }

    async getFeeStats(): Promise<FeeStatsResult> {
        return await this.withRateLimit(async () => {
            const serverAny = this.server as any;
            if (typeof serverAny.getFeeStats !== "function") {
                throw new Error("RPC server does not support getFeeStats");
            }

            const response = await serverAny.getFeeStats();
            const inclusionFee = response.sorobanInclusionFee ?? response.inclusionFee;
            if (!inclusionFee) {
                throw new Error("RPC fee stats response did not include inclusion fee data");
            }

            const baseFeeStroops = parseFeeStat(inclusionFee.p50 ?? inclusionFee.mode ?? inclusionFee.min);
            const surgeFeeStroops = parseFeeStat(
                inclusionFee.p95 ?? inclusionFee.p90 ?? inclusionFee.max ?? baseFeeStroops,
            );
            const surgePricingMultiplier = baseFeeStroops > 0
                ? Math.max(surgeFeeStroops / baseFeeStroops, 1)
                : 1;

            return {
                latestLedger: typeof response.latestLedger === "number" ? response.latestLedger : undefined,
                baseFeeStroops,
                surgeFeeStroops,
                surgePricingMultiplier,
            };
        });
    }

    async getContractInstanceEntry(contractId: string): Promise<ContractInstanceResult | null> {
        const contract = new Contract(contractId);
        const instanceKey = contract.getFootprint();
        const entryKeyXdr = instanceKey.toXDR("base64");

        const response = await this.server.getLedgerEntries(instanceKey);

        if (!response.entries || response.entries.length === 0) return null;

        const entry = response.entries[0]!;
        const latestLedger = response.latestLedger;
        const liveUntilLedgerSeq = entry.liveUntilLedgerSeq ?? 0;
        const lastModifiedLedgerSeq = entry.lastModifiedLedgerSeq ?? 0;
        const remainingTTL = liveUntilLedgerSeq - latestLedger;

        let executableType = "unknown";
        let wasmHash: string | null = null;

        try {
            const contractData = entry.val.contractData();
            const instance = contractData.val().instance();
            const executable = instance.executable();
            executableType = executable.switch().name;

            if (executableType === "contractExecutableWasm") {
                wasmHash = executable.wasmHash().toString("hex");
            }
        } catch (error) {
            logger.error("Error extracting executable info from contract instance entry", error);
        }

        return {
            entryKeyXdr,
            executableType,
            latestLedger,
            liveUntilLedgerSeq,
            lastModifiedLedgerSeq,
            remainingTTL,
            wasmHash,
        };
    }

    async getWasmCodeEntry(
        wasmHashHex: string
    ): Promise<SorokeepLedgerEntryResult | null> {
        const wasmHash = Buffer.from(wasmHashHex, "hex");
        const wasmKey = xdr.LedgerKey.contractCode(
            new xdr.LedgerKeyContractCode({ hash: wasmHash })
        );
        const entryKeyXdr = wasmKey.toXDR("base64");

        const response = await this.server.getLedgerEntries(wasmKey);
        if (!response.entries || response.entries.length === 0) return null;

        const entry = response.entries[0]!;
        const latestLedger = response.latestLedger;
        const liveUntilLedgerSeq = entry.liveUntilLedgerSeq ?? 0;
        const lastModifiedLedgerSeq = entry.lastModifiedLedgerSeq ?? 0;

        return {
            entryKeyXdr,
            latestLedger,
            liveUntilLedgerSeq,
            lastModifiedLedgerSeq,
            remainingTTL: liveUntilLedgerSeq - latestLedger,
        };
    }

    async getEntryTTLs(entryKeyXdrs: string[]): Promise<EntryTTLsResult> {
        const keys = entryKeyXdrs.map((xdrStr) =>
            xdr.LedgerKey.fromXDR(xdrStr, "base64")
        );

        const response = await this.server.getLedgerEntries(...keys);
        const latestLedger = response.latestLedger;

        const entries = (response.entries ?? []).map((entry) => {
            const liveUntilLedgerSeq = entry.liveUntilLedgerSeq ?? 0;
            const lastModifiedLedgerSeq = entry.lastModifiedLedgerSeq ?? 0;
            return {
                entryKeyXdr: entry.key.toXDR("base64"),
                latestLedger,
                liveUntilLedgerSeq,
                lastModifiedLedgerSeq,
                remainingTTL: liveUntilLedgerSeq - latestLedger,
            };
        });

        return { latestLedger, entries };
    }

    async getContractStorageEntries(entryKeyXdrs: string[]): Promise<ContractStorageEntryResult[]> {
        if (entryKeyXdrs.length === 0) return [];
        const keys = entryKeyXdrs.map((xdrStr) =>
            xdr.LedgerKey.fromXDR(xdrStr, "base64")
        );

        const response = await this.server.getLedgerEntries(...keys);
        const latestLedger = response.latestLedger;

        return (response.entries ?? []).map((entry) => {
            const liveUntilLedgerSeq = entry.liveUntilLedgerSeq ?? 0;
            const lastModifiedLedgerSeq = entry.lastModifiedLedgerSeq ?? 0;
            let valXdr: string | undefined;
            try {
                if (entry.val && entry.val.switch().name === "contractData") {
                    valXdr = entry.val.contractData().val().toXDR("base64");
                }
            } catch {
                // ignore
            }
            return {
                entryKeyXdr: entry.key.toXDR("base64"),
                latestLedger,
                liveUntilLedgerSeq,
                lastModifiedLedgerSeq,
                remainingTTL: liveUntilLedgerSeq - latestLedger,
                valXdr,
            };
        });
    }

    async getSacDecimals(contractId: string): Promise<number> {
        try {
            const passphrase = await this.getNetworkPassphrase();
            const contract = new Contract(contractId);
            const op = contract.call("decimals");
            const account = new Account("GAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAWHF", "0");

            const tx = new TransactionBuilder(account, {
                fee: "100",
                networkPassphrase: passphrase,
            })
                .addOperation(op)
                .setTimeout(30)
                .build();

            const sim = await this.server.simulateTransaction(tx);
            if (!rpc.Api.isSimulationError(sim)) {
                const successSim = sim as rpc.Api.SimulateTransactionSuccessResponse;
                if (successSim.result?.retval) {
                    const retval = successSim.result.retval;
                    if (retval.switch().name === "scvU32") {
                        return retval.u32();
                    }
                }
            }
        } catch {
            // fallback below
        }
        return 7; // standard SAC / XLM asset decimals
    }

    /**
     * Call the 'get_monitored_keys' view method on a contract.
     * Returns an array of XDR strings for the keys.
     */
