    const actual = await importOriginal() as any;
    return {
        ...actual,
        getDatabase: () => mockDb,
    };
});

describe("resources command", () => {
    const contractID = "CBEOJUP5FU6KKOEZ7RMTSKZ7YLBS5D6LVATIGCESOGXSZEQ2UWQFKZW6";
    let consoleLogSpy: any;
    let consoleErrorSpy: any;

    beforeEach(() => {
        mockDb = getDatabaseForTesting();
        insertContract(mockDb, {
            id: contractID,
            name: "sample-contract",
            network: "testnet",
        });

        consoleLogSpy = vi.spyOn(console, "log").mockImplementation(() => {});
        consoleErrorSpy = vi.spyOn(console, "error").mockImplementation(() => {});
        vi.spyOn(process, "exit").mockImplementation(() => {
            throw new Error("process.exit called");
        });
    });

    afterEach(() => {
        vi.restoreAllMocks();
    });

    it("prints resource usage averages when records exist", () => {
        insertResourceAlertConfig(mockDb, {
            contract_id: contractID,
            channel_type: "webhook",
            channel_target: "https://example.com",
            cpu_limit: 100000000,
            mem_limit: 50000000,
        });

        const config = mockDb.prepare("SELECT id FROM resource_alert_configs WHERE contract_id = ?").get(contractID);
        expect(config).toBeDefined();

        recordResourceAlertFired(mockDb, {
            resource_alert_config_id: config.id,
            resource_type: "cpu",
            usage: 50_000_000,
            limit: 100_000_000,
            usage_percent: 50,
            fired_at_ledger: 100,
        });

        recordResourceAlertFired(mockDb, {
            resource_alert_config_id: config.id,
            resource_type: "cpu",
            usage: 80_000_000,
            limit: 100_000_000,
            usage_percent: 80,
            fired_at_ledger: 101,
        });

        recordResourceAlertFired(mockDb, {
            resource_alert_config_id: config.id,
            resource_type: "memory",
            usage: 20_000_000,
            limit: 50_000_000,
            usage_percent: 40,
            fired_at_ledger: 102,
        });

        const program = new Command();
        registerResourcesCommand(program);

        program.parse(["node", "sorokeep", "resources", contractID]);

        expect(consoleLogSpy).toHaveBeenCalledWith(expect.stringContaining("Resource Usage Trends"));
        expect(consoleLogSpy).toHaveBeenCalledWith(expect.stringContaining("CPU"));
        expect(consoleLogSpy).toHaveBeenCalledWith(expect.stringContaining("Memory"));
    });

    it("accepts --period and filters history records", () => {
        insertResourceAlertConfig(mockDb, {
            contract_id: contractID,
            channel_type: "webhook",
            channel_target: "https://example.com",
            cpu_limit: 100000000,
            mem_limit: 50000000,
        });

        const config = mockDb.prepare("SELECT id FROM resource_alert_configs WHERE contract_id = ?").get(contractID);

        recordResourceAlertFired(mockDb, {
            resource_alert_config_id: config.id,
            resource_type: "cpu",
            usage: 50_000_000,
            limit: 100_000_000,
            usage_percent: 50,
            fired_at_ledger: 100,
        });

        const program = new Command();
        registerResourcesCommand(program);

        program.parse(["node", "sorokeep", "resources", contractID, "--period", "30"]);

        expect(consoleLogSpy).toHaveBeenCalledWith(expect.stringContaining("Resource Usage Trends"));
    });

    it("errors when --period is invalid", () => {
        const program = new Command();
        registerResourcesCommand(program);

        expect(() => {
            program.parse(["node", "sorokeep", "resources", contractID, "--period", "-5"]);
        }).toThrow("process.exit called");

        expect(consoleErrorSpy).toHaveBeenCalledWith(expect.stringContaining("--period must be a positive integer"));
    });

    it("errors when contract is not registered", () => {
        const program = new Command();
        registerResourcesCommand(program);

        expect(() => {
            program.parse(["node", "sorokeep", "resources", "CUNKNOWNCONTRACTID"]);
        }).toThrow("process.exit called");

        expect(consoleErrorSpy).toHaveBeenCalledWith(expect.stringContaining("not found. Run 'sorokeep watch' first."));
    });
});

import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import { registerRestoreCommand } from "../../src/commands/restore";
import { Command } from "commander";

// Mock modules before importing them
vi.mock("../../src/db/database", () => ({
  getDatabase: vi.fn(() => ({}))
}));

vi.mock("../../src/db/repositories", () => ({
  getContract: vi.fn(),
  getEntriesForContract: vi.fn()
}));

vi.mock("../../src/core/extension", () => ({
  restoreEntries: vi.fn()
}));

import * as dbLib from "../../src/db/database";
import * as repos from "../../src/db/repositories";
import * as extensionLib from "../../src/core/extension";

describe("Restore Command CLI", () => {
    let program: Command;
    let mockExit: any;
    let mockError: any;
    let mockLog: any;
    let actionFn: (contractId: string, options: any) => Promise<void>;

    beforeEach(() => {
        program = new Command();

        vi.spyOn(Command.prototype, "action").mockImplementation(function (this: any, fn: any) {
            actionFn = fn;
            return this;
        });

        registerRestoreCommand(program);

        mockExit = vi.spyOn(process, "exit").mockImplementation((() => {}) as any);
        mockError = vi.spyOn(console, "error").mockImplementation(() => {});
        mockLog = vi.spyOn(console, "log").mockImplementation(() => {});
        vi.mocked(dbLib.getDatabase).mockReturnValue({} as any);
    });

    afterEach(() => {
        vi.restoreAllMocks();
    });

    it("exits with 1 if contract is not found", async () => {
        vi.mocked(repos.getContract).mockReturnValue(undefined as any);

        await actionFn("MISSING_ID", {});
        expect(mockExit).toHaveBeenCalledWith(1);
        expect(mockError).toHaveBeenCalledWith(expect.stringContaining("not found"));
    });

    it("exits with 1 if no keypair provided", async () => {
        vi.mocked(repos.getContract).mockReturnValue({ id: "X", network: "testnet" } as any);

        await actionFn("VALID_ID", {});
        expect(mockExit).toHaveBeenCalledWith(1);
        expect(mockError).toHaveBeenCalledWith(expect.stringContaining("--keypair or --keypair-env is required"));
    });

    it("exits with 1 if --keypair-env points to unset env var", async () => {
        vi.mocked(repos.getContract).mockReturnValue({ id: "X", network: "testnet" } as any);
        delete process.env["NONEXISTENT_VAR_FOR_TEST"];

        await actionFn("VALID_ID", { keypairEnv: "NONEXISTENT_VAR_FOR_TEST" });
        expect(mockExit).toHaveBeenCalledWith(1);
        expect(mockError).toHaveBeenCalledWith(expect.stringContaining("is not set"));
    });

    it("exits with 1 if both --entry and --all are provided", async () => {
        vi.mocked(repos.getContract).mockReturnValue({ id: "X", network: "testnet" } as any);

        await actionFn("VALID_ID", { keypair: "SKEY", all: true, entry: ["AAAA"] });
        expect(mockExit).toHaveBeenCalledWith(1);
        expect(mockError).toHaveBeenCalledWith(expect.stringContaining("Use either --entry"));
    });

    it("exits with 1 if neither --entry nor --all is provided", async () => {
        vi.mocked(repos.getContract).mockReturnValue({ id: "X", network: "testnet" } as any);

        await actionFn("VALID_ID", { keypair: "SKEY", entry: [] });
        expect(mockExit).toHaveBeenCalledWith(1);
        expect(mockError).toHaveBeenCalledWith(expect.stringContaining("Specify --entry"));
    });

    it("prints 'No entries to restore' when --all but contract has no entries", async () => {
        vi.mocked(repos.getContract).mockReturnValue({ id: "X", network: "testnet" } as any);
        vi.mocked(repos.getEntriesForContract).mockReturnValue([]);

        await actionFn("VALID_ID", { keypair: "SKEY", all: true });
        expect(mockLog).toHaveBeenCalledWith(expect.stringContaining("No entries to restore"));
    });

    it("restores entries successfully with --all and outputs tx hash and fee", async () => {
        vi.mocked(repos.getContract).mockReturnValue({ id: "X", network: "testnet", name: "MyContract" } as any);
        vi.mocked(repos.getEntriesForContract).mockReturnValue([
            { entry_key_xdr: "AAAA" } as any,
        ]);
        vi.mocked(extensionLib.restoreEntries).mockResolvedValue({
            success: true,
            entriesRestored: 1,
            txHash: "abcd1234",
            ledger: 5000,
            feeCharged: 500,
        } as any);

        await actionFn("VALID_ID", { keypair: "SKEY", all: true });
        expect(mockLog).toHaveBeenCalledWith(expect.stringContaining("abcd1234"));
        expect(mockLog).toHaveBeenCalledWith(expect.stringContaining("500 stroops"));
    });

    it("exits with 1 when restore fails", async () => {
        vi.mocked(repos.getContract).mockReturnValue({ id: "X", network: "testnet" } as any);
        vi.mocked(repos.getEntriesForContract).mockReturnValue([
            { entry_key_xdr: "AAAA" } as any,
        ]);
        vi.mocked(extensionLib.restoreEntries).mockResolvedValue({
            success: false,
            error: "Insufficient funds",
        } as any);

        await actionFn("VALID_ID", { keypair: "SKEY", all: true });
        expect(mockExit).toHaveBeenCalledWith(1);
    });

    it("restores specific entries with --entry", async () => {
        vi.mocked(repos.getContract).mockReturnValue({ id: "X", network: "testnet" } as any);
        vi.mocked(extensionLib.restoreEntries).mockResolvedValue({
            success: true,
            entriesRestored: 2,
            txHash: "efgh5678",
            ledger: 6000,
        } as any);

        await actionFn("VALID_ID", { keypair: "SKEY", entry: ["KEY1", "KEY2"] });
        expect(extensionLib.restoreEntries).toHaveBeenCalledWith(
            expect.anything(),
            "VALID_ID",
            ["KEY1", "KEY2"],
            "SKEY"
        );
    });
});

import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import { Command } from "commander";
import * as dbLib from "../../src/db/database";
import { ContractNotFoundError } from "../../src/core/status";
import * as statusModule from "../../src/core/status";
import { registerStatusCommand } from "../../src/commands/status";

vi.mock("../../src/db/database", () => ({
    getDatabase: vi.fn(),
}));

vi.mock("../../src/core/status", async (importOriginal) => {
    const actual = await importOriginal<typeof import("../../src/core/status")>();
    return {
        ...actual,
        getContractStatus: vi.fn(),
    };
});

describe("status command", () => {
    const contractID = "CBEOJUP5FU6KKOEZ7RMTSKZ7YLBS5D6LVATIGCESOGXSZEQ2UWQFKZW6";
    let actionFn: (contractId: string, options: { json?: boolean }) => void;
    let mockExit: ReturnType<typeof vi.spyOn>;
    let mockLog: ReturnType<typeof vi.spyOn>;

    beforeEach(() => {
        const program = new Command();
        vi.spyOn(Command.prototype, "action").mockImplementation(function (this: any, fn: any) {
            actionFn = fn;
            return this;
        });

        registerStatusCommand(program);
        mockExit = vi.spyOn(process, "exit").mockImplementation((() => undefined) as never);
        mockLog = vi.spyOn(console, "log").mockImplementation(() => {});
        vi.mocked(dbLib.getDatabase).mockReturnValue({} as any);
    });

    afterEach(() => {
        vi.restoreAllMocks();
    });

    it("prints JSON payload when --json is provided", () => {
        vi.mocked(statusModule.getContractStatus).mockReturnValue({
            contractId: contractID,
            name: "sample-contract",
            network: "testnet",
            lastCheckedLedger: 400000,
            entries: [
                {
                    label: "Instance",
                    entryType: "instance",
                    entryKeyXdr: "AAAAA",
                    liveUntilLedger: 500000,
                    remainingTTL: 100000,
                    approximateTimeRemaining: "~1 day",
                    status: "ok",
                },
            ],
        } as any);

        actionFn(contractID, { json: true });

        const output = mockLog.mock.calls.map((args) => args.join(" ")).join("\n");
        const parsed = JSON.parse(output);

        expect(parsed).toMatchObject({
            contractId: contractID,
            name: "sample-contract",
            network: "testnet",
            lastCheckedLedger: 400000,
        });
        expect(parsed.entries).toHaveLength(1);
        expect(output).not.toContain("\u001b[");
    });

    it("prints human-readable output by default", () => {
        vi.mocked(statusModule.getContractStatus).mockReturnValue({
            contractId: contractID,
            name: "sample-contract",
            network: "testnet",
            lastCheckedLedger: 400000,
            entries: [
                {
                    label: "Instance",
                    entryType: "instance",
                    entryKeyXdr: "AAAAA",
                    liveUntilLedger: 500000,
                    remainingTTL: 100000,
                    approximateTimeRemaining: "~1 day",
                    status: "ok",
                },
            ],
        } as any);

        actionFn(contractID, { json: false });

        const output = mockLog.mock.calls.map((args) => args.join(" ")).join("\n");

        expect(output).toContain("Network:");
        expect(output).toContain("TTL:");
        expect(output).not.toContain("\"contractId\"");
    });

    it("exits with code 1 if contract is not found", () => {
        vi.mocked(statusModule.getContractStatus).mockImplementation(() => {
            throw new ContractNotFoundError("MISSING_ID");
        });

        actionFn("MISSING_ID", { json: false });

        expect(mockExit).toHaveBeenCalledWith(1);
        expect(mockLog).toHaveBeenCalledWith(expect.stringContaining("is not registered"));
    });

    it("re-throws unknown errors", () => {
        vi.mocked(statusModule.getContractStatus).mockImplementation(() => {
            throw new Error("DB Corrupt");
        });

        expect(() => actionFn("VALID_ID", { json: false })).toThrow("DB Corrupt");
    });
});

import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import { registerWatchCommand } from "../../src/commands/watch";
import { Command } from "commander";
import readline from "node:readline";

// Mock modules before importing them
vi.mock("../../src/db/database", () => ({
  getDatabase: vi.fn(() => ({ close: vi.fn() }))
}));

vi.mock("../../src/core/watch", () => ({
  watchContract: vi.fn()
}));

vi.mock("../../src/utils/watch-config", () => ({
  loadWatchContractsFile: vi.fn()
}));

vi.mock("../../src/db/repositories", () => ({
  getContract: vi.fn(),
  deleteContract: vi.fn()
}));

import * as dbLib from "../../src/db/database";
import * as watchCore from "../../src/core/watch";
import * as watchConfig from "../../src/utils/watch-config";
import * as repositories from "../../src/db/repositories";

describe("Watch Command CLI", () => {
  let program: Command;
  let mockExit: any;
  let mockLog: any;
  let mockWarn: any;
  let actionFn: (contractId: string | undefined, options: any) => Promise<void>;

  beforeEach(() => {
    program = new Command();

    vi.spyOn(Command.prototype, "action").mockImplementation(function (
      this: any,
      fn: any,
    ) {
      if (this.name() === "watch") actionFn = fn;
      return this;
    });

    registerWatchCommand(program);

    mockExit = vi.spyOn(process, "exit").mockImplementation((() => {}) as any);
    mockLog = vi.spyOn(console, "log").mockImplementation(() => {});
    mockWarn = vi.spyOn(console, "warn").mockImplementation(() => {});
    vi.spyOn(dbLib, "getDatabase").mockReturnValue({} as any);
    vi.mocked(watchCore.watchContract).mockReset();
  });

  afterEach(() => {
    vi.restoreAllMocks();
  });

  it("exits with 1 when watchContract returns success=false", async () => {
    vi.mocked(watchCore.watchContract).mockResolvedValue({
      success: false,
      error: "Failed to fetch instance",
    } as any);

    const validId = "CBEOJUP5FU6KKOEZ7RMTSKZ7YLBS5D6LVATIGCESOGXSZEQ2UWQFKZW6";
    await actionFn(validId, { network: "testnet" });
    expect(mockExit).toHaveBeenCalledWith(1);
  });

  it("prints contract details on success (with name)", async () => {
    vi.mocked(watchCore.watchContract).mockResolvedValue({
      success: true,
      instance: { remainingTTL: 100000 },
      wasm: { remainingTTL: 200000 },
    } as any);

    const validId = "CBEOJUP5FU6KKOEZ7RMTSKZ7YLBS5D6LVATIGCESOGXSZEQ2UWQFKZW6";
    await actionFn(validId, { network: "testnet", name: "MyContract" });

    expect(mockLog).toHaveBeenCalledWith(expect.stringContaining("MyContract"));
    expect(mockLog).toHaveBeenCalledWith(expect.stringContaining("testnet"));
  });

  it("prints WASM TTL when wasm entry exists", async () => {
    vi.mocked(watchCore.watchContract).mockResolvedValue({
      success: true,
      instance: { remainingTTL: 100000 },
      wasm: { remainingTTL: 50000 },
    } as any);

    const validId = "CBEOJUP5FU6KKOEZ7RMTSKZ7YLBS5D6LVATIGCESOGXSZEQ2UWQFKZW6";
    await actionFn(validId, { network: "testnet" });

    expect(mockLog).toHaveBeenCalledWith(
      expect.stringContaining("WASM Code TTL"),
    );
  });

  it("prints WASM warning when present", async () => {
    vi.mocked(watchCore.watchContract).mockResolvedValue({
      success: true,
      instance: { remainingTTL: 100000 },
      wasm: null,
      wasmWarning: "WASM could not be fetched",
    } as any);

    const validId = "CBEOJUP5FU6KKOEZ7RMTSKZ7YLBS5D6LVATIGCESOGXSZEQ2UWQFKZW6";
    await actionFn(validId, { network: "testnet" });

    expect(mockWarn).toHaveBeenCalledWith(
      expect.stringContaining("WASM could not be fetched"),
    );
  });

  it("passes correct options to watchContract", async () => {
    vi.mocked(watchCore.watchContract).mockResolvedValue({
      success: true,
      instance: { remainingTTL: 100000 },
      wasm: null,
    } as any);

    const validId = "CBEOJUP5FU6KKOEZ7RMTSKZ7YLBS5D6LVATIGCESOGXSZEQ2UWQFKZW6";
    await actionFn(validId, {
      network: "mainnet",
      name: "TestContract",
      rpcUrl: "https://custom-rpc.com",
      storageKeys: "key1,key2",
      noIntrospection: true,
    });

    expect(watchCore.watchContract).toHaveBeenCalledWith(
      expect.anything(),
      expect.objectContaining({
        contractId: validId,
        network: "mainnet",
        name: "TestContract",
        rpcUrl: "https://custom-rpc.com",
        storageKeys: "key1,key2",
        noIntrospection: true,
      }),
    );
  });

  it("exits with 1 when watchContract throws an error", async () => {
    vi.mocked(watchCore.watchContract).mockRejectedValue(
      new Error("Network timeout"),
    );

    const validId = "CBEOJUP5FU6KKOEZ7RMTSKZ7YLBS5D6LVATIGCESOGXSZEQ2UWQFKZW6";
    await actionFn(validId, { network: "testnet" });
    expect(mockExit).toHaveBeenCalledWith(1);
  });

  it("counts entries correctly (instance + wasm + storage keys)", async () => {
    vi.mocked(watchCore.watchContract).mockResolvedValue({
      success: true,
      instance: { remainingTTL: 100000 },
      wasm: { remainingTTL: 200000 },
    } as any);

    const validId = "CBEOJUP5FU6KKOEZ7RMTSKZ7YLBS5D6LVATIGCESOGXSZEQ2UWQFKZW6";
    await actionFn(validId, { network: "testnet", storageKeys: "a,b,c" });

    // 1 (instance) + 1 (wasm) + 3 (storage keys) = 5
    expect(mockLog).toHaveBeenCalledWith(expect.stringContaining("5"));
  });

  it("registers all contracts listed in a YAML file", async () => {
    const firstId = "CBEOJUP5FU6KKOEZ7RMTSKZ7YLBS5D6LVATIGCESOGXSZEQ2UWQFKZW6";
    const secondId = "CD2R4QQV6KJ6P7JX5TURH6K7W2K4XQ6G5V5VJQ4X6UR6P6JQ6P2M4ABC";

    vi.mocked(watchConfig.loadWatchContractsFile).mockReturnValue([
      { contractId: firstId, name: "Alpha", network: "testnet" },
      {
        contractId: secondId,
        name: "Beta",
        network: "mainnet",
        rpcUrl: "https://rpc.example",
        storageKeys: ["key-1", "key-2"],
      },
    ]);

    vi.mocked(watchCore.watchContract)
      .mockResolvedValueOnce({
        success: true,
        instance: { remainingTTL: 100 },
        wasm: null,
      } as any)
      .mockResolvedValueOnce({
        success: true,
        instance: { remainingTTL: 200 },
        wasm: null,
      } as any);

    await actionFn(undefined, {
      fromFile: "contracts.yaml",
      network: "testnet",
    });

    expect(watchCore.watchContract).toHaveBeenCalledTimes(2);
    expect(watchCore.watchContract).toHaveBeenNthCalledWith(
      1,
      expect.anything(),
      expect.objectContaining({
        contractId: firstId,
        name: "Alpha",
        network: "testnet",
      }),
    );
    expect(watchCore.watchContract).toHaveBeenNthCalledWith(
      2,
      expect.anything(),
      expect.objectContaining({
        contractId: secondId,
        name: "Beta",
        network: "mainnet",
        rpcUrl: "https://rpc.example",
        storageKeys: ["key-1", "key-2"],
      }),
    );
    expect(mockLog).toHaveBeenCalledWith(
      expect.stringContaining("Batch registration summary"),
    );
    expect(mockLog).toHaveBeenCalledWith(expect.stringContaining("Alpha"));
    expect(mockLog).toHaveBeenCalledWith(expect.stringContaining("Beta"));
  });

  it("prints a success and failure summary for batch registration and exits 1 when any contract fails", async () => {
    const firstId = "CBEOJUP5FU6KKOEZ7RMTSKZ7YLBS5D6LVATIGCESOGXSZEQ2UWQFKZW6";
    const secondId = "CD2R4QQV6KJ6P7JX5TURH6K7W2K4XQ6G5V5VJQ4X6UR6P6JQ6P2M4ABC";

    vi.mocked(watchConfig.loadWatchContractsFile).mockReturnValue([
      { contractId: firstId, name: "Alpha", network: "testnet" },
      { contractId: secondId, name: "Beta", network: "mainnet" },
    ]);

    vi.mocked(watchCore.watchContract)
      .mockResolvedValueOnce({
        success: true,
        instance: { remainingTTL: 100 },
        wasm: null,
      } as any)
      .mockResolvedValueOnce({
        success: false,
        error: "Already registered on another network",
      } as any);

    await actionFn(undefined, {
      fromFile: "contracts.json",
      network: "testnet",
    });

    expect(mockLog).toHaveBeenCalledWith(expect.stringContaining("SUCCESS"));
    expect(mockLog).toHaveBeenCalledWith(expect.stringContaining("FAILED"));
    expect(mockLog).toHaveBeenCalledWith(
      expect.stringContaining("1 succeeded"),
    );
    expect(mockLog).toHaveBeenCalledWith(expect.stringContaining("1 failed"));
    expect(mockExit).toHaveBeenCalledWith(1);
  });
});

describe("Unwatch Command CLI", () => {
  let program: Command;
  let mockExit: any;
  let mockLog: any;
  let unwatchActionFn: (contractId: string, options: any) => Promise<void>;
  let mockRl: any;

  beforeEach(() => {
    program = new Command();

    vi.spyOn(Command.prototype, "action").mockImplementation(function (
      this: any,
      fn: any,
    ) {
      if (this.name() === "unwatch") unwatchActionFn = fn;
      return this;
    });

    registerWatchCommand(program);

    mockExit = vi.spyOn(process, "exit").mockImplementation((() => {}) as any);
    mockLog = vi.spyOn(console, "log").mockImplementation(() => {});
    vi.spyOn(dbLib, "getDatabase").mockReturnValue({ close: vi.fn() } as any);
    
    mockRl = {
      question: vi.fn(),
      close: vi.fn()
    };
    vi.spyOn(readline, "createInterface").mockReturnValue(mockRl as any);
    vi.mocked(repositories.deleteContract).mockReset();
  });

  afterEach(() => {
    vi.restoreAllMocks();
  });

  it("exits with 1 when no contract id provided", async () => {
    // commander requires it, but if bypassed:
    await unwatchActionFn(undefined as any, {});
    expect(mockExit).toHaveBeenCalledWith(1);
  });

  it("exits with 1 when contract is not found", async () => {
    vi.mocked(repositories.getContract).mockReturnValue(undefined);
    await unwatchActionFn("CDEF1234", {});
    expect(mockExit).toHaveBeenCalledWith(1);
    expect(mockLog).toHaveBeenCalledWith(expect.stringContaining("not being watched"));
  });

  it("deletes contract directly when --yes is passed", async () => {
