    it("should test complex switch statements with fallthrough", () => {
        function switchWithFallthrough(type: string, subtype: string): string {
            let result = '';

            switch (type) {
                case 'A':
                    result += 'A';
                    switch (subtype) {
                        case '1':
                            result += '1';
                            break;
                        case '2':
                            result += '2';
                            // fallthrough
                        case '3':
                            result += '3';
                            break;
                        default:
                            result += 'X';
                    }
                    break;
                case 'B':
                    result += 'B';
                    if (subtype === '1') {
                        result += '1';
                    } else if (subtype === '2') {
                        result += '2';
                    } else {
                        result += 'Y';
                    }
                    break;
                case 'C':
                case 'D':
                    result += type;
                    result += subtype ? subtype : 'Z';
                    break;
                default:
                    result += 'DEFAULT';
                    if (subtype) {
                        result += '-' + subtype;
                    }
            }

            return result;
        }

        expect(switchWithFallthrough('A', '1')).toBe('A1');
        expect(switchWithFallthrough('A', '2')).toBe('A23'); // fallthrough
        expect(switchWithFallthrough('A', '3')).toBe('A3');
        expect(switchWithFallthrough('A', 'other')).toBe('AX');
        expect(switchWithFallthrough('B', '1')).toBe('B1');
        expect(switchWithFallthrough('B', '2')).toBe('B2');
        expect(switchWithFallthrough('B', 'other')).toBe('BY');
        expect(switchWithFallthrough('C', '1')).toBe('C1');
        expect(switchWithFallthrough('D', '2')).toBe('D2');
        expect(switchWithFallthrough('C', '')).toBe('CZ');
        expect(switchWithFallthrough('UNKNOWN', 'sub')).toBe('DEFAULT-sub');
        expect(switchWithFallthrough('UNKNOWN', '')).toBe('DEFAULT');
    });
});

