      if (c > 0) {
        result += '-c-pos';
      } else {
        result += '-c-neg';
      }

      return result;
    };

    // Test all 8 combinations (2^3)
    expect(testFunction(1, 1, 1)).toBe('positive-b-pos-c-pos');
    expect(testFunction(1, 1, 0)).toBe('positive-b-pos-c-neg');
    expect(testFunction(1, 0, 1)).toBe('positive-b-neg-c-pos');
    expect(testFunction(1, 0, 0)).toBe('positive-b-neg-c-neg');
    expect(testFunction(0, 1, 1)).toBe('negative-b-pos-c-pos');
    expect(testFunction(0, 1, 0)).toBe('negative-b-pos-c-neg');
    expect(testFunction(0, 0, 1)).toBe('negative-b-neg-c-pos');
    expect(testFunction(0, 0, 0)).toBe('negative-b-neg-c-neg');
  });

  it('should cover switch statement branches', () => {
    const switchFunction = (type: string, value: number) => {
      let result = '';

      switch (type) {
        case 'add':
          result = value > 0 ? 'add-pos' : 'add-neg';
          break;
        case 'subtract':
          result = value > 0 ? 'sub-pos' : 'sub-neg';
          break;
        case 'multiply':
          result = value > 0 ? 'mul-pos' : 'mul-neg';
          break;
        default:
          result = value > 0 ? 'def-pos' : 'def-neg';
      }

      return result;
    };

    expect(switchFunction('add', 5)).toBe('add-pos');
    expect(switchFunction('add', -5)).toBe('add-neg');
    expect(switchFunction('subtract', 3)).toBe('sub-pos');
    expect(switchFunction('subtract', -3)).toBe('sub-neg');
    expect(switchFunction('multiply', 2)).toBe('mul-pos');
    expect(switchFunction('multiply', -2)).toBe('mul-neg');
    expect(switchFunction('unknown', 1)).toBe('def-pos');
    expect(switchFunction('unknown', -1)).toBe('def-neg');
  });

  it('should cover ternary operator branches', () => {
    const ternaryFunction = (x: number, y: number) => {
      const result1 = x > 0 ? 'x-pos' : 'x-neg';
      const result2 = y > 0 ? 'y-pos' : 'y-neg';
      const result3 = (x > 0 && y > 0) ? 'both-pos' : 
                     (x > 0 || y > 0) ? 'one-pos' : 'both-neg';

      return `${result1}-${result2}-${result3}`;
    };

    expect(ternaryFunction(1, 1)).toBe('x-pos-y-pos-both-pos');
    expect(ternaryFunction(1, -1)).toBe('x-pos-y-neg-one-pos');
    expect(ternaryFunction(-1, 1)).toBe('x-neg-y-pos-one-pos');
    expect(ternaryFunction(-1, -1)).toBe('x-neg-y-neg-both-neg');
  });

  it('should cover loop with conditional branches', () => {
    const loopFunction = (limit: number) => {
      const results: string[] = [];

      for (let i = 0; i < limit; i++) {
        if (i % 2 === 0) {
          if (i % 4 === 0) {
            results.push('even-divisible-by-4');
          } else {
            results.push('even-not-divisible-by-4');
          }
        } else {
          if (i % 3 === 0) {
            results.push('odd-divisible-by-3');
          } else {
            results.push('odd-not-divisible-by-3');
          }
        }
      }

      return results;
    };

    const results = loopFunction(12);
    expect(results).toHaveLength(12);
    expect(results[0]).toBe('even-divisible-by-4'); // 0
    expect(results[1]).toBe('odd-not-divisible-by-3'); // 1
    expect(results[2]).toBe('even-not-divisible-by-4'); // 2
    expect(results[3]).toBe('odd-divisible-by-3'); // 3
    expect(results[4]).toBe('even-divisible-by-4'); // 4
    expect(results[9]).toBe('odd-divisible-by-3'); // 9
  });

  it('should cover try-catch branches', () => {
    const errorFunction = (shouldThrow: boolean, value: string) => {
      try {
        if (shouldThrow) {
          throw new Error('Test error');
        }

        if (value.length > 5) {
          return 'long-string';
        } else {
          return 'short-string';
        }
      } catch (error) {
        if (error instanceof Error) {
          return 'caught-error';
        } else {
          return 'unknown-error';
        }
      }
    };

    expect(errorFunction(false, 'short')).toBe('short-string');
    expect(errorFunction(false, 'verylongstring')).toBe('long-string');
    expect(errorFunction(true, 'anything')).toBe('caught-error');
  });

  it('should cover object property branches', () => {
    const objectFunction = (obj: any) => {
      let result = '';

      if (obj && typeof obj === 'object') {
        if (obj.hasOwnProperty('name')) {
          result += obj.name ? 'has-name' : 'empty-name';
        } else {
          result += 'no-name-prop';
        }

        if (obj.hasOwnProperty('value')) {
          result += obj.value > 0 ? '-pos-value' : '-neg-value';
        } else {
          result += '-no-value-prop';
        }
      } else {
        result = 'not-object';
      }

      return result;
    };

    expect(objectFunction({ name: 'test', value: 5 })).toBe('has-name-pos-value');
    expect(objectFunction({ name: '', value: -5 })).toBe('empty-name-neg-value');
    expect(objectFunction({ name: 'test' })).toBe('has-name-no-value-prop');
    expect(objectFunction({ value: 0 })).toBe('no-name-prop-neg-value');
    expect(objectFunction({})).toBe('no-name-prop-no-value-prop');
    expect(objectFunction(null)).toBe('not-object');
    expect(objectFunction('string')).toBe('not-object');
  });

  it('should cover array processing branches', () => {
    const arrayFunction = (arr: number[]) => {
      let evenCount = 0;
      let oddCount = 0;
      let positiveCount = 0;
      let negativeCount = 0;

      arr.forEach(num => {
        if (num % 2 === 0) {
          evenCount++;
        } else {
          oddCount++;
        }

        if (num > 0) {
          positiveCount++;
        } else if (num < 0) {
          negativeCount++;
        }
      });

      return {
        evenCount,
        oddCount,
        positiveCount,
        negativeCount,
        hasEven: evenCount > 0,
        hasOdd: oddCount > 0,
        hasPositive: positiveCount > 0,
        hasNegative: negativeCount > 0
      };
    };

    const result1 = arrayFunction([1, 2, 3, 4, -1, -2]);
    expect(result1.evenCount).toBe(3); // 2, 4, -2 are even
    expect(result1.oddCount).toBe(3); // 1, 3, -1 are odd
    expect(result1.positiveCount).toBe(4);
    expect(result1.negativeCount).toBe(2);
    expect(result1.hasEven).toBe(true);
    expect(result1.hasOdd).toBe(true);
    expect(result1.hasPositive).toBe(true);
    expect(result1.hasNegative).toBe(true);

    const result2 = arrayFunction([0]);
    expect(result2.evenCount).toBe(1);
    expect(result2.oddCount).toBe(0);
    expect(result2.hasPositive).toBe(false);
    expect(result2.hasNegative).toBe(false);
  });
});

import { describe, it, expect } from "vitest";

// Ultra aggressive branch coverage blitz
describe("Ultra Branch Coverage Blitz", () => {
    it("should hit every possible branch combination", () => {
        function ultraBranchFunction(
            a: any, b: any, c: any, d: any, e: any, 
            config?: { mode?: string; flags?: boolean[]; data?: any[] }
        ): any {
            const result: any = { 
                score: 0, 
                paths: [], 
                data: [],
                flags: { a: false, b: false, c: false, d: false, e: false },
                metadata: { 
                    processed: 0, 
                    skipped: 0, 
                    errors: 0, 
                    branches: 0,
                    conditions: 0,
                    switches: 0
                }
            };

            // Multi-level conditional nesting
            if (a) {
                result.flags.a = true;
                result.metadata.branches++;
                if (b) {
                    result.flags.b = true;
                    result.metadata.branches++;
                    if (c) {
                        result.flags.c = true;
                        result.metadata.branches++;
                        if (d) {
                            result.flags.d = true;
                            result.metadata.branches++;
                            if (e) {
                                result.flags.e = true;
                                result.score += 100;
                                result.paths.push('all-true');
                            } else {
                                result.score += 80;
                                result.paths.push('abcd-true');
                            }
                        } else {
                            result.score += 60;
                            if (e) {
                                result.paths.push('abce-true');
                            } else {
                                result.paths.push('abc-true');
                            }
                        }
                    } else {
                        result.score += 40;
                        if (d && e) {
                            result.paths.push('abde-true');
                        } else if (d || e) {
                            result.paths.push('abd-or-abe');
                        } else {
                            result.paths.push('ab-only');
                        }
                    }
                } else {
                    result.score += 20;
                    if (c && d && e) {
                        result.paths.push('acde-true');
                    } else if (c && d) {
                        result.paths.push('acd-true');
                    } else if (c && e) {
                        result.paths.push('ace-true');
                    } else if (d && e) {
                        result.paths.push('ade-true');
                    } else if (c) {
                        result.paths.push('ac-only');
                    } else if (d) {
                        result.paths.push('ad-only');
                    } else if (e) {
                        result.paths.push('ae-only');
                    } else {
                        result.paths.push('a-only');
                    }
                }
            } else {
                result.score += 10;
                if (b && c && d && e) {
                    result.paths.push('bcde-true');
                } else if (b && c && d) {
                    result.paths.push('bcd-true');
                } else if (b && c && e) {
                    result.paths.push('bce-true');
                } else if (b && d && e) {
                    result.paths.push('bde-true');
                } else if (c && d && e) {
                    result.paths.push('cde-true');
                } else if (b && c) {
                    result.paths.push('bc-only');
                } else if (b && d) {
                    result.paths.push('bd-only');
                } else if (b && e) {
                    result.paths.push('be-only');
                } else if (c && d) {
                    result.paths.push('cd-only');
                } else if (c && e) {
                    result.paths.push('ce-only');
                } else if (d && e) {
                    result.paths.push('de-only');
                } else if (b) {
                    result.paths.push('b-only');
                } else if (c) {
                    result.paths.push('c-only');
                } else if (d) {
                    result.paths.push('d-only');
                } else if (e) {
                    result.paths.push('e-only');
                } else {
                    result.paths.push('none-true');
                }
            }

            // Configuration-based branching
            if (config) {
                result.metadata.processed++;

                switch (config.mode) {
                    case 'fast':
                        result.metadata.switches++;
                        result.score *= 2;
                        if (config.flags) {
                            for (let i = 0; i < config.flags.length; i++) {
                                if (config.flags[i]) {
                                    result.data.push({ index: i, value: true });
                                } else {
                                    result.data.push({ index: i, value: false });
                                }
                            }
                        }
                        break;

                    case 'slow':
                        result.metadata.switches++;
                        result.score *= 1.5;
                        if (config.data) {
                            for (const item of config.data) {
                                if (item === null) {
                                    result.data.push('null');
                                } else if (item === undefined) {
                                    result.data.push('undefined');
                                } else if (typeof item === 'string') {
                                    if (item.length === 0) {
                                        result.data.push('empty');
                                    } else if (item.length < 5) {
                                        result.data.push('short');
                                    } else {
                                        result.data.push('long');
                                    }
                                } else if (typeof item === 'number') {
                                    if (item === 0) {
                                        result.data.push('zero');
                                    } else if (item > 0) {
                                        result.data.push('positive');
                                    } else {
                                        result.data.push('negative');
                                    }
                                } else if (typeof item === 'boolean') {
                                    result.data.push(item ? 'true' : 'false');
                                } else {
                                    result.data.push('other');
                                }
                            }
                        }
                        break;

                    case 'balanced':
                        result.metadata.switches++;
                        if (config.flags && config.data) {
                            if (config.flags.length === config.data.length) {
                                result.score *= 1.8;
                                result.paths.push('equal-lengths');
                            } else if (config.flags.length > config.data.length) {
                                result.score *= 1.3;
                                result.paths.push('more-flags');
                            } else {
                                result.score *= 1.1;
                                result.paths.push('more-data');
                            }
                        } else if (config.flags) {
                            result.paths.push('flags-only');
                        } else if (config.data) {
                            result.paths.push('data-only');
                        } else {
                            result.paths.push('no-config-data');
                        }
                        break;

                    case 'debug':
                        result.metadata.switches++;
                        result.paths.push('debug-mode');
                        try {
                            if (config.data && Array.isArray(config.data)) {
                                config.data.forEach((item, index) => {
                                    if (typeof item === 'object' && item !== null) {
                                        if ('error' in item) {
                                            throw new Error(`Error at index ${index}`);
                                        } else if ('value' in item) {
                                            result.data.push({ index, value: item.value });
                                        } else {
                                            result.data.push({ index, empty: true });
                                        }
                                    } else {
                                        result.data.push({ index, primitive: item });
                                    }
                                });
                            }
                        } catch (error) {
                            result.metadata.errors++;
                            result.paths.push('debug-error');
                        }
                        break;

                    case null:
                    case undefined:
                        result.metadata.switches++;
                        result.paths.push('null-mode');
                        break;

                    default:
                        result.metadata.switches++;
                        result.paths.push('unknown-mode');
                        if (typeof config.mode === 'string') {
                            if (config.mode.startsWith('test')) {
                                result.paths.push('test-prefix');
                            } else if (config.mode.endsWith('ing')) {
                                result.paths.push('ing-suffix');
                            } else if (config.mode.includes('special')) {
                                result.paths.push('special-keyword');
                            }
                        }
                }
            } else {
                result.paths.push('no-config');
                result.metadata.skipped++;
            }

            // Final scoring and classification
            if (result.score > 200) {
                result.paths.push('high-score');
            } else if (result.score > 100) {
                result.paths.push('medium-score');
            } else if (result.score > 50) {
                result.paths.push('low-score');
            } else {
                result.paths.push('minimal-score');
            }

            return result;
        }

        // Test all possible combinations
        const testCases = [
            // All true/false combinations for primary flags
            [true, true, true, true, true],
            [true, true, true, true, false],
            [true, true, true, false, true],
            [true, true, true, false, false],
            [true, true, false, true, true],
            [true, true, false, true, false],
            [true, true, false, false, true],
            [true, true, false, false, false],
            [true, false, true, true, true],
            [true, false, true, true, false],
            [true, false, true, false, true],
            [true, false, true, false, false],
            [true, false, false, true, true],
            [true, false, false, true, false],
            [true, false, false, false, true],
            [true, false, false, false, false],
            [false, true, true, true, true],
            [false, true, true, true, false],
            [false, true, true, false, true],
            [false, true, true, false, false],
            [false, true, false, true, true],
            [false, true, false, true, false],
            [false, true, false, false, true],
            [false, true, false, false, false],
            [false, false, true, true, true],
            [false, false, true, true, false],
            [false, false, true, false, true],
            [false, false, true, false, false],
            [false, false, false, true, true],
            [false, false, false, true, false],
            [false, false, false, false, true],
            [false, false, false, false, false],
        ];

        // Test with different config combinations
        const configs = [
            undefined,
            { mode: 'fast', flags: [true, false, true] },
            { mode: 'slow', data: [null, undefined, '', 'hello', 0, 5, -3, true, false, 'other'] },
            { mode: 'balanced', flags: [true, false], data: ['a', 'b'] },
            { mode: 'balanced', flags: [true, false, true], data: ['a'] },
            { mode: 'balanced', flags: [true], data: ['a', 'b', 'c'] },
            { mode: 'debug', data: [{ value: 'test' }, { error: true }, { empty: 'obj' }, 42] },
            { mode: null },
            { mode: undefined },
            { mode: 'testing' },
            { mode: 'running' },
            { mode: 'special-case' },
            { mode: 'unknown' }
        ];

        let totalResults = 0;
        for (const testCase of testCases) {
            for (const config of configs) {
                const result = ultraBranchFunction(
                    testCase[0], testCase[1], testCase[2], testCase[3], testCase[4], 
                    config
                );
                expect(result).toBeDefined();
                expect(result.paths).toBeInstanceOf(Array);
                expect(result.metadata.branches).toBeGreaterThan(-1);
                totalResults++;
            }
        }

        // Specific edge cases
        expect(ultraBranchFunction(true, true, true, true, true).paths).toContain('all-true');
        expect(ultraBranchFunction(false, false, false, false, false).paths).toContain('none-true');

        const debugResult = ultraBranchFunction(false, false, false, false, false, {
            mode: 'debug',
            data: [{ error: true }]
        });
        expect(debugResult.paths).toContain('debug-error');

        console.log(`Tested ${totalResults} branch combinations`);
        expect(totalResults).toBe(testCases.length * configs.length);
    });
});

/**
 * TDD tests for rate limiter DB layer — countExtensionsInLastHour
 *
 * These tests are written FIRST, before the implementation, following the
 * strict Test-Driven Development requirements of issues #133 and #142.
 *
 * countExtensionsInLastHour(db, contractId) must:
 *   - Return 0 when there are no extension records for the contract.
 *   - Count only records from the past hour (executed_at >= now - 1 hour).
 *   - Exclude records older than one hour.
 *   - Count records for the given contract only (not other contracts).
 *   - Handle the boundary: a record at exactly one hour ago is excluded
 *     (strictly greater-than).
 */

import { describe, it, expect, beforeEach, afterEach } from "vitest";
import type Database from "better-sqlite3";
import { getDatabaseForTesting } from "../../src/db/database.js";
import {
    insertContract,
    upsertEntry,
    recordExtension,
    countExtensionsInLastHour,
} from "../../src/db/repositories.js";

// ─── Helpers ────────────────────────────────────────────────────────────────

function seedContractWithEntry(
    db: Database.Database,
    contractId = "CTEST1111111111111111111111111111111111111111111111111111",
    network = "testnet",
): number {
    insertContract(db, { id: contractId, name: "Rate Limit Test", network });
    upsertEntry(db, {
        contract_id: contractId,
        entry_key_xdr: "instance-key-xdr",
        entry_type: "instance",
        label: "Contract Instance",
        live_until_ledger: 2_500_000,
        last_modified_ledger: 2_400_000,
        discovery_source: "deterministic",
    });

    const row = db
        .prepare("SELECT id FROM contract_entries WHERE contract_id = ?")
        .get(contractId) as { id: number };
    return row.id;
}

/**
 * Insert a raw extension_history record with an explicit executed_at timestamp
 * so we can test time-windowing without waiting for real time to pass.
 */
function insertExtensionAt(
    db: Database.Database,
    contractId: string,
    entryId: number,
    executedAt: string, // ISO-8601 string
): void {
    db.prepare(`
        INSERT INTO extension_history
            (contract_id, contract_entry_id, old_ttl_ledgers, new_ttl_ledgers,
             tx_hash, executed_at_ledger, executed_at)
        VALUES (?, ?, 1000, 2000, 'txhash-' || hex(randomblob(4)), 100, ?)
    `).run(contractId, entryId, executedAt);
}

// ─── Tests ───────────────────────────────────────────────────────────────────

describe("countExtensionsInLastHour", () => {
    let db: Database.Database;

    beforeEach(() => {
        db = getDatabaseForTesting();
    });

    afterEach(() => {
        db.close();
    });

    it("returns 0 when no extension records exist for the contract", () => {
        seedContractWithEntry(db);
        const count = countExtensionsInLastHour(db, "CTEST1111111111111111111111111111111111111111111111111111");
        expect(count).toBe(0);
    });

    it("returns 0 for a contract that has never had extensions", () => {
        seedContractWithEntry(db);
        // Seed a different contract WITH extensions to ensure isolation
        const other = "COTHER111111111111111111111111111111111111111111111111111";
        const otherId = seedContractWithEntry(db, other);
        const now = new Date().toISOString();
        insertExtensionAt(db, other, otherId, now);

        const count = countExtensionsInLastHour(
            db,
            "CTEST1111111111111111111111111111111111111111111111111111",
        );
        expect(count).toBe(0);
    });

    it("counts one extension that just happened (within the last hour)", () => {
        const contractId = "CTEST1111111111111111111111111111111111111111111111111111";
        const entryId = seedContractWithEntry(db, contractId);

        const now = new Date().toISOString();
        insertExtensionAt(db, contractId, entryId, now);

        const count = countExtensionsInLastHour(db, contractId);
        expect(count).toBe(1);
    });

    it("counts multiple extensions within the last hour", () => {
        const contractId = "CTEST1111111111111111111111111111111111111111111111111111";
        const entryId = seedContractWithEntry(db, contractId);

        const thirtyMinAgo = new Date(Date.now() - 30 * 60 * 1000).toISOString();
        const fifteenMinAgo = new Date(Date.now() - 15 * 60 * 1000).toISOString();
        const now = new Date().toISOString();

        insertExtensionAt(db, contractId, entryId, thirtyMinAgo);
        insertExtensionAt(db, contractId, entryId, fifteenMinAgo);
        insertExtensionAt(db, contractId, entryId, now);

        const count = countExtensionsInLastHour(db, contractId);
        expect(count).toBe(3);
    });

    it("excludes extensions older than one hour", () => {
        const contractId = "CTEST1111111111111111111111111111111111111111111111111111";
        const entryId = seedContractWithEntry(db, contractId);

        // 2 hours ago — should be excluded
        const twoHoursAgo = new Date(Date.now() - 2 * 60 * 60 * 1000).toISOString();
        insertExtensionAt(db, contractId, entryId, twoHoursAgo);

        const count = countExtensionsInLastHour(db, contractId);
        expect(count).toBe(0);
    });

    it("counts only extensions within the last hour when mixed with older ones", () => {
        const contractId = "CTEST1111111111111111111111111111111111111111111111111111";
        const entryId = seedContractWithEntry(db, contractId);

        // Old — excluded
        const twoHoursAgo = new Date(Date.now() - 2 * 60 * 60 * 1000).toISOString();
        insertExtensionAt(db, contractId, entryId, twoHoursAgo);

        // Recent — counted
        const twentyMinAgo = new Date(Date.now() - 20 * 60 * 1000).toISOString();
        insertExtensionAt(db, contractId, entryId, twentyMinAgo);
        const now = new Date().toISOString();
        insertExtensionAt(db, contractId, entryId, now);

        const count = countExtensionsInLastHour(db, contractId);
        expect(count).toBe(2);
    });

    it("counts extensions only for the specified contract (not other contracts)", () => {
        const contract1 = "CTEST1111111111111111111111111111111111111111111111111111";
        const contract2 = "COTHER111111111111111111111111111111111111111111111111111";

        const entryId1 = seedContractWithEntry(db, contract1);
        const entryId2 = seedContractWithEntry(db, contract2);

        const now = new Date().toISOString();
        // 3 extensions for contract1, 5 for contract2
        for (let i = 0; i < 3; i++) {
            insertExtensionAt(db, contract1, entryId1, now);
        }
        for (let i = 0; i < 5; i++) {
            insertExtensionAt(db, contract2, entryId2, now);
        }

        expect(countExtensionsInLastHour(db, contract1)).toBe(3);
        expect(countExtensionsInLastHour(db, contract2)).toBe(5);
    });

    it("handles the boundary: record at exactly 61 minutes ago is excluded", () => {
        const contractId = "CTEST1111111111111111111111111111111111111111111111111111";
        const entryId = seedContractWithEntry(db, contractId);

        // 61 minutes ago — should be excluded (outside the 1-hour window)
        const sixtyOneMinAgo = new Date(Date.now() - 61 * 60 * 1000).toISOString();
        insertExtensionAt(db, contractId, entryId, sixtyOneMinAgo);

        const count = countExtensionsInLastHour(db, contractId);
        expect(count).toBe(0);
    });

    it("returns the correct count when exactly at the hourly rate limit (5)", () => {
        const contractId = "CTEST1111111111111111111111111111111111111111111111111111";
        const entryId = seedContractWithEntry(db, contractId);

        const now = new Date().toISOString();
        for (let i = 0; i < 5; i++) {
            insertExtensionAt(db, contractId, entryId, now);
        }

        const count = countExtensionsInLastHour(db, contractId);
        expect(count).toBe(5);
    });
});

