    describe("executeWithRetry", () => {
        beforeEach(() => {
            vi.useFakeTimers();
        });

        afterEach(() => {
            vi.useRealTimers();
            vi.restoreAllMocks();
        });

        it("Succeeds if transient failure resolves within retries", async () => {
            let attempts = 0;
            const action = vi.fn().mockImplementation(async () => {
                attempts++;
                if (attempts < 3) {
                    const error = new Error("503 Service Unavailable");
                    (error as any).response = { status: 503 };
                    throw error;
                }
                return "success";
            });

            const promise = executeWithRetry(action);

            // Advance timers for backoff
            await vi.advanceTimersByTimeAsync(1000); // 1st retry
            await vi.advanceTimersByTimeAsync(2000); // 2nd retry

            const result = await promise;

            expect(result).toBe("success");
            expect(action).toHaveBeenCalledTimes(3);
        });

        it("Network timeouts trigger retry attempts", async () => {
            const action = vi.fn().mockImplementation(async () => {
                const error = new Error("timeout");
                (error as any).code = "ETIMEDOUT";
                throw error;
            });

            let error: any;
            const promise = executeWithRetry(action).catch(e => { error = e; });

            // Fast forward through all retries: 1s, 2s, 4s
            await vi.advanceTimersByTimeAsync(1000);
            await vi.advanceTimersByTimeAsync(2000);
            await vi.advanceTimersByTimeAsync(4000);

            await promise;
            expect(error).toBeDefined();
            expect(error.message).toBe("timeout");
            expect(action).toHaveBeenCalledTimes(4); // 1 initial + 3 retries
        });

        it("Retries on ECONNRESET error", async () => {
            const action = vi.fn().mockImplementation(async () => {
                const error = new Error("connection reset");
                (error as any).code = "ECONNRESET";
                throw error;
            });

            let error: any;
            const promise = executeWithRetry(action).catch(e => { error = e; });

            await vi.advanceTimersByTimeAsync(1000);
            await vi.advanceTimersByTimeAsync(2000);
            await vi.advanceTimersByTimeAsync(4000);

            await promise;
            expect(action).toHaveBeenCalledTimes(4);
        });

        it("Retries on timeout in error message", async () => {
            const action = vi.fn().mockImplementation(async () => {
                const error = new Error("request timeout");
                throw error;
            });

            let error: any;
            const promise = executeWithRetry(action).catch(e => { error = e; });

            await vi.advanceTimersByTimeAsync(1000);
            await vi.advanceTimersByTimeAsync(2000);
            await vi.advanceTimersByTimeAsync(4000);

            await promise;
            expect(action).toHaveBeenCalledTimes(4);
        });

        it("Retries on 429 rate limit error", async () => {
            const action = vi.fn().mockImplementation(async () => {
                const error = new Error("Too many requests");
                (error as any).response = { status: 429 };
                throw error;
            });

            let error: any;
            const promise = executeWithRetry(action).catch(e => { error = e; });

            await vi.advanceTimersByTimeAsync(1000);
            await vi.advanceTimersByTimeAsync(2000);
            await vi.advanceTimersByTimeAsync(4000);

            await promise;
            expect(action).toHaveBeenCalledTimes(4);
        });

        it("Retries on 500 server error", async () => {
            const action = vi.fn().mockImplementation(async () => {
                const error = new Error("Internal server error");
                (error as any).response = { status: 500 };
                throw error;
            });

            let error: any;
            const promise = executeWithRetry(action).catch(e => { error = e; });

            await vi.advanceTimersByTimeAsync(1000);
            await vi.advanceTimersByTimeAsync(2000);
            await vi.advanceTimersByTimeAsync(4000);

            await promise;
            expect(action).toHaveBeenCalledTimes(4);
        });

        it("Does not retry on non-transient errors like 400 Bad Request", async () => {
            const action = vi.fn().mockImplementation(async () => {
                const error = new Error("400 Bad Request");
                (error as any).response = { status: 400 };
                throw error;
            });

            await expect(executeWithRetry(action)).rejects.toThrow("400 Bad Request");
            expect(action).toHaveBeenCalledTimes(1);
        });

        it("Does not retry on 404 Not Found", async () => {
            const action = vi.fn().mockImplementation(async () => {
                const error = new Error("Not found");
                (error as any).response = { status: 404 };
                throw error;
            });

            await expect(executeWithRetry(action)).rejects.toThrow("Not found");
            expect(action).toHaveBeenCalledTimes(1);
        });
    });

